export default [
  {id:"halacha-0001",q:"כמה שעות ממתינים אחרי אכילת בשר כדי לאכול מאכלי חלב?",options:["1","3","4","6"],answer:3,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"לפי מרן השולחן ערוך ממתינים שש שעות, וכך גם אחרי עוף."},
  {id:"halacha-0002",q:"אכלתי שניצל עוף – האם צריך להמתין אחריו לפני מאכל חלבי?",options:["לא, עוף אינו נחשב בשר","רק שעה אחת","רק שלוש שעות","כן, שש שעות כמו בבשר"],answer:3,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"דין ההמתנה של שש שעות חל גם על בשר עוף."},
  {id:"halacha-0003",q:"מאיזה רגע סופרים את שש השעות שבין בשר לחלב?",options:["מברכת המזון","מסוף הסעודה כולה","מתחילת הסעודה","מסיום אכילת הבשר"],answer:3,category:"halacha",difficulty:2,tags:["כשרות","בשר וחלב"],note:"סופרים מרגע שסיים לאכול את הבשר עצמו."},
  {id:"halacha-0004",q:"במקום צורך, אחרי כמה זמן מבשר אפשר להקל ולאכול מאכל חלבי?",options:["חמש שעות וחצי","ארבע שעות","שלוש שעות","שעה אחת"],answer:0,category:"halacha",difficulty:3,tags:["כשרות","בשר וחלב"],note:"לכתחילה שש שעות, ובמקום צורך אפשר להקל אחרי חמש וחצי."},
  {id:"halacha-0005",q:"חולה קצת (שאין בו סכנה) אכל בשר – כמה זמן עליו להמתין לפני מאכל חלב?",options:["יממה","שש שעות","שלוש שעות","שעה אחת"],answer:3,category:"halacha",difficulty:2,tags:["כשרות","בשר וחלב","בריאות"],note:"לחולה, אפילו אין בו סכנה, מותר לאכול חלבי שעה אחרי בשר."},
  {id:"halacha-0006",q:"טעמתי מרוטב התבשיל הבשרי בלשון ומיד פלטתי. האם עליי להמתין שש שעות?",options:["כן, שש שעות מלאות","צריך להמתין שלוש שעות","לא, אין צריך להמתין","צריך לצום עד הערב"],answer:2,category:"halacha",difficulty:2,tags:["כשרות","בשר וחלב"],note:"הטועם ופולט מיד אינו צריך להמתין."},
  {id:"halacha-0007",q:"ירקות שבושלו בסיר בשרי נקי, בלי שום בשר בתבשיל – מה הדין?",options:["צריך להמתין אחריהם שעה","צריך להמתין אחריהם שש שעות","אסור לאכול אותם כלל","מותר לאכול אותם אפילו עם גבינה"],answer:3,category:"halacha",difficulty:2,tags:["כשרות","בשר וחלב"],note:"תבשיל פרווה שבושל בכלי בשרי (בלי בשר בתוכו) מותר אף עם גבינה."},
  {id:"halacha-0008",q:"אכלתי גבינה צהובה ואני רוצה לאכול בשר. מה צריך לעשות לפי מעיקר הדין?",options:["להמתין שלוש שעות","לא לאכול בשר באותו יום","לקנח ולהדיח את הפה ולנקות ידיים","להמתין שש שעות"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"מעיקר הדין מותר מיד, אחרי קינוח בפת או פרי, הדחת הפה ובדיקת הידיים."},
  {id:"halacha-0009",q:"שתיתי קפה עם חלב ועכשיו אני רוצה לאכול בשר. מה מספיק?",options:["המתנה של שעה","המתנה של שש שעות","נטילת ידיים וקינוח בפת","הדחת הפה במים או במשקה"],answer:3,category:"halacha",difficulty:2,tags:["כשרות","בשר וחלב"],note:"אחרי חלב נוזלי די בהדחת הפה בלבד."},
  {id:"halacha-0010",q:"במה מקנחים את הפה בין גבינה לבשר?",options:["בלעיסת פת או פירות","בקמח","בירקות עלים","בלעיסת תמרים"],answer:0,category:"halacha",difficulty:2,tags:["כשרות","בשר וחלב"],note:"קמח, תמרים וירקות נדבקים בחניכיים ואינם מועילים לקינוח."},
  {id:"halacha-0011",q:"לפי מעיקר הדין, אחרי אכילת גבינה ולפני עוף – האם צריך קינוח והדחה?",options:["לא, זה נאמר רק בבשר בהמה וחיה","צריך להמתין שש שעות","כן, בדיוק כמו בבשר","צריך להמתין שעה"],answer:0,category:"halacha",difficulty:3,tags:["כשרות","בשר וחלב"],note:"מעיקר הדין בעוף אין צורך, ויש שנהגו להחמיר."},
  {id:"halacha-0012",q:"אני לא בטוח אם כבר עברו שש שעות מהבשר. מה הדין?",options:["חייב להמתין עוד שש שעות","חייב להמתין עד מחר","מותר להקל ולאכול חלבי","צריך לשאול שני עדים"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"ספק דרבנן לקולא."},
  {id:"halacha-0013",q:"אכלתי בשר לפני שעתיים. מותר לי להכין לילדים ארוחה חלבית?",options:["לא, עד שיעברו שש שעות","כן, מותר להתעסק במאכלי חלב","רק בכפפות","רק אם מישהו נוסף בבית"],answer:1,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"המתעסק במאכלי חלב לסעודה אחרת אינו עובר על כלום."},
  {id:"halacha-0014",q:"אכלתי בשר, ומיד אחרי הארוחה אני רוצה גלידה פרווה בטעם חלבי. מה הדין?",options:["אסור עד שש שעות","מותר","מותר רק אחרי שעה","מותר רק אם אין רואים"],answer:1,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"מותר, ואין לחשוש למראית העין גם בחלב צמחי."},
  {id:"halacha-0015",q:"אפשר להתחיל ארוחה חלבית לפני שעברו שש שעות מהבשר?",options:["לא, אסור אפילו לשבת לשולחן","רק אם מברכים קודם ברכת המזון","כן, אם בהתחלה אוכלים רק פרווה","רק בשבת"],answer:2,category:"halacha",difficulty:3,tags:["כשרות","בשר וחלב"],note:"אוכלים קודם סלטים פרווה, ואת החלבי רק אחרי שעברו שש שעות."},
  {id:"halacha-0016",q:"עברו שש שעות ומצאתי שארית בשר בין השיניים. מה עושים?",options:["מוציאים אותה ולא בולעים","בולעים ואוכלים חלבי","ממתינים עוד שש שעות","מותר לבלוע אחרי שתייה"],answer:0,category:"halacha",difficulty:2,tags:["כשרות","בשר וחלב"],note:"צריך להסיר את הבשר לפני האכילה החלבית."},
  {id:"halacha-0017",q:"אכלתי בטעות גבינה לפני שעברו שש שעות מבשר. מה עליי לעשות?",options:["להפסיק מיד ולשאול חכם על תשובה","לתת צדקה בשיעור קבוע","לצום יום שלם","להמשיך לאכול, כבר לא משנה"],answer:0,category:"halacha",difficulty:2,tags:["כשרות","בשר וחלב"],note:"אין צריך להתענות, אבל מפסיקים ושואלים חכם."},
  {id:"halacha-0018",q:"בירכתי על יוגורט ונזכרתי שלא עברו שש שעות מהבשר. מה עושים?",options:["אוכלים את כל היוגורט","טועמים מעט כדי שהברכה לא תהיה לבטלה","יורקים ולא טועמים כלל","אומרים ברוך שם כבוד ומשליכים"],answer:1,category:"halacha",difficulty:3,tags:["כשרות","בשר וחלב","ברכה לבטלה"],note:"לפי הדין טועם מעט ממה שבירך עליו."},
  {id:"halacha-0019",q:"אכלתי צ'יפס שטוגן באותו שמן שבו טוגנו קודם שניצלים. לפי המנהג הנפוץ גם אצל הספרדים – מה הדין?",options:["ממתינים שש שעות","ממתינים שלוש שעות","אין צריך להמתין כלל","ממתינים שעה"],answer:0,category:"halacha",difficulty:3,tags:["כשרות","בשר וחלב"],note:"דומה למאכל שהתבשל עם בשר, והמנהג להמתין שש שעות."},
  {id:"halacha-0020",q:"ילד קטן שהגיע לגיל חינוך אכל בשר. מה הדין לגבי ארוחת חלב חיונית?",options:["מותר להקל ולא להמתין שש שעות","אסור לו חלבי באותו יום","חייב להמתין שש שעות מלאות","חייב להמתין שלוש שעות"],answer:0,category:"halacha",difficulty:3,tags:["כשרות","בשר וחלב","ילדים"],note:"במאכל חיוני מקלים לקטן; אבל ממתקים חלביים אין לתת לו תוך שש שעות."},
  {id:"halacha-0021",q:"שני חברים יושבים לאכול יחד, אחד בשרי ואחד חלבי. מה מאפשר להם לאכול באותו שולחן?",options:["אין צורך בשום דבר","רק שולחן נפרד לגמרי","רק אם הם בני אותה משפחה","היכר ביניהם, כמו מפה נפרדת"],answer:3,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"עושים היכר, כגון מפה לכל אחד או לחם באמצע ביניהם."},
  {id:"halacha-0022",q:"במסעדה אני אוכל בשר, ולידי יושב אדם זר שאוכל גבינה. מה הדין?",options:["אין בזה חשש","חייבים לעשות היכר","צריך לעבור שולחן","צריך להפסיק לאכול"],answer:0,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב","נסיעות"],note:"האיסור הוא רק בשני אנשים המכירים זה את זה."},
  {id:"halacha-0023",q:"מותר להניח במקרר סיר עם תבשיל בשרי ליד קנקן חלב?",options:["לא, צריך מדף נפרד","כן, מותר לכתחילה","רק אם הסיר עטוף בניילון","רק במקרר כפול"],answer:1,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"מצד הדין אין לחשוש שייפול מזה לזה."},
  {id:"halacha-0024",q:"מה הדין לפי מנהג הספרדים בכוס זכוכית שהודחה היטב – לבשר ולחלב?",options:["רק לחלבי","רק לבשרי","מותר להשתמש בה לשניהם","צריך להגעיל אותה בכל פעם"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"זכוכית אינה בולעת, ולספרדים מותר לשניהם אחרי הדחה."},
  {id:"halacha-0025",q:"האם צריך כיריים גז נפרדות לבשרי ולחלבי?",options:["לא, אפשר לבשל על אותן כיריים","רק בבית חדש","רק אם יש מקום","כן, חובה"],answer:0,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"מותר לבשל בשר וחלב על אותן כיריים."},
  {id:"halacha-0026",q:"מותר לאפות בשר ומאפה חלבי יחד באותו תא של תנור?",options:["לא, האדים מעבירים טעם","כן, אם הם מכוסים חלקית","כן, אם התנור חזק","כן, אם האפייה קצרה"],answer:0,category:"halacha",difficulty:2,tags:["כשרות","בשר וחלב"],note:"בתא אחד אסור לאפות בשר וחלב יחד."},
  {id:"halacha-0027",q:"צליתי עוף בתנור. מה צריך כדי לאפות בו אחר כך מאפה חלבי במגש חלבי?",options:["אין שום דרך","שיעבור שבוע","שיעברו שש שעות בלבד","שיעברו 24 שעות ויחממו את התנור כחצי שעה"],answer:3,category:"halacha",difficulty:3,tags:["כשרות","בשר וחלב"],note:"אחרי 24 שעות ובחימום מוקדם של התנור – מותר."},
  {id:"halacha-0028",q:"צליתי היום בשר בתנור. מותר לאפות בו עוגה פרווה ולאכול אותה עם קפה חלב?",options:["רק אם אופים בתבנית סגורה","לא, רק אחרי 24 שעות","כן, אחרי ניקוי התנור משאריות","לא, העוגה נעשית בשרית"],answer:2,category:"halacha",difficulty:2,tags:["כשרות","בשר וחלב"],note:"מותר באותו יום, אחרי ניקוי בסמרטוט לח."},
  {id:"halacha-0029",q:"אפיתי לחם באותו תנור ובאותו זמן עם צלי בשר. מותר לאכול את הלחם עם גבינה?",options:["כן, אין בעיה","כן, אם הלחם היה בצד השני","רק אם עברו שש שעות","לא, הוא אסור עם חלבי"],answer:3,category:"halacha",difficulty:3,tags:["כשרות","בשר וחלב"],note:"לחם שנאפה יחד עם צלי בתנורים שלנו אסור עם חלב."},
  {id:"halacha-0030",q:"נהגו כל ישראל שיהיו במטבח שתי מערכות כלים. איזה סט מקובל לסמן?",options:["אין מנהג לסמן","הכלים החלביים","הכלים הבשריים","כלי הפרווה"],answer:1,category:"halacha",difficulty:1,tags:["כשרות","מטבח"],note:"נהגו לסמן את כלי החלב כדי להבחין ביניהם."},
  {id:"halacha-0031",q:"לפי מנהג הספרדים, מותר להגעיל סיר בשרי כדי להשתמש בו לחלבי?",options:["לא, לעולם לא","רק בפסח","כן, ואין מנהג להחמיר בזה","רק סיר חדש"],answer:2,category:"halacha",difficulty:2,tags:["כשרות","הגעלה"],note:"לבני ספרד מותר להגעיל כלי מבשר לחלב וכן להפך."},
  {id:"halacha-0032",q:"בישלתי בשר בסיר פיירקס. לפי מרן ומנהג הספרדים – אפשר לבשל בו אחר כך חלבי?",options:["רק אחרי הגעלה","כן, אחרי הדחה ושפשוף טובים","רק אחרי ליבון","לא, הוא נעשה בשרי לתמיד"],answer:1,category:"halacha",difficulty:3,tags:["כשרות","בשר וחלב"],note:"פיירקס ודורלקס אינם בולעים לדעת מרן."},
  {id:"halacha-0033",q:"איך מכשירים את המיקרוגל לשימוש בשרי וחלבי?",options:["מספיק לנגב במגבת","רק בהחלפת הצלחת","ניקוי, הרתחת מים עם חומר ניקוי ושימוש בקופסה סגורה","אי אפשר בשום אופן"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","מטבח"],note:"אחר הניקוי וההרתחה משתמשים תמיד בכלי סגור היטב."},
  {id:"halacha-0034",q:"טוסטר לחיצה שהכנו בו טוסט עם נקניק – אפשר להכין בו טוסט גבינה?",options:["לא, מייחדים טוסטר לכל סוג","כן, אחרי ניגוב","כן, אחרי 24 שעות","כן, אם מניחים נייר אפייה"],answer:0,category:"halacha",difficulty:2,tags:["כשרות","בשר וחלב"],note:"אפשר להכשירו רק בליבון, ולכן מייחדים טוסטר לחלב ולבשר."},
  {id:"halacha-0035",q:"מותר לבחוש תה בכוס בעזרת כפית חלבית באמצע ארוחה בשרית?",options:["לא, אסור לגמרי","רק בכפית פלסטיק","רק אם התה קר","כן, הכוס היא כלי שני"],answer:3,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"בחישה בכלי שני מותרת."},
  {id:"halacha-0036",q:"אכלתי בשר. מותר לי לשתות תה בכוס שמשמשת לחלבי?",options:["רק אחרי שש שעות","רק בכוס חד פעמית","כן, כשהכוס נקייה","לא, אסור"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"כשהכוס נקייה ורחוצה – מותר."},
  {id:"halacha-0037",q:"חתכתי גבינה בסכין בשרית נקייה. מה דין הגבינה?",options:["מותרת רק אחרי שטיפה ברותחים","צריך לחתוך ממנה עובי אצבע","אסורה","מותרת"],answer:3,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"כשהסכין מקונחת ונקייה – הגבינה מותרת."},
  {id:"halacha-0038",q:"חתכתי בצל בסכין בשרית. מה עושים לפני שמגישים אותו בסלט חלבי?",options:["אין צורך בכלום","חותכים ממקום החתך כעובי אצבע","זורקים את כל הבצל","שוטפים במים קרים בלבד"],answer:1,category:"halacha",difficulty:3,tags:["כשרות","בשר וחלב"],note:"דבר חריף בולע; חותכים מקום החתך או טועמים שאין בו טעם בשר."},
  {id:"halacha-0039",q:"נפל קצת חלב לתבשיל בשרי. מה בודקים כדי לדעת אם התבשיל מותר?",options:["אם רואים את החלב","אם החלב היה קר","אם יש בתבשיל פי 60 מהחלב","אם עברה שעה"],answer:2,category:"halacha",difficulty:2,tags:["כשרות","בשר וחלב"],note:"בתערובת בשר וחלב משערים בשישים."},
  {id:"halacha-0040",q:"כמה צריך שיהיה בתבשיל כנגד האיסור שנפל לתוכו, כדי שיתבטל?",options:["10","30","60","100"],answer:2,category:"halacha",difficulty:2,tags:["כשרות","ביטול"],note:"משערים בשישים."},
  {id:"halacha-0041",q:"הכנסתי בטעות כף חלבית לסיר בשרי רותח. לפי מה משערים שישים?",options:["לפי משקל הבשר בלבד","לפי כל הכף","לפי החלק של הכף שנכנס לתבשיל","לפי כל הסיר"],answer:2,category:"halacha",difficulty:3,tags:["כשרות","בשר וחלב"],note:"משערים לפי מה שנכנס בתבשיל; אם קשה לשער – שואלים רב."},
  {id:"halacha-0042",q:"בישלתי בטעות מאכל חלבי בסיר בשרי שלא השתמשו בו יותר מיממה. מה דין האוכל?",options:["אסור באכילה","מותר רק לגוי","מותר בדיעבד","מותר רק עם בשר"],answer:2,category:"halacha",difficulty:3,tags:["כשרות","בשר וחלב"],note:"אחרי 24 שעות האוכל מותר בדיעבד, ואת הסיר מגעילים."},
  {id:"halacha-0043",q:"מי שבישל בכוונה מאכל כשר בסיר לא כשר (שלא היה בשימוש 24 שעות) – מה דין התבשיל?",options:["מותר לגמרי","מותר רק לאחרים","אסור לו לאכול, משום קנס","מותר בשבת בלבד"],answer:2,category:"halacha",difficulty:3,tags:["כשרות","קנס"],note:"בדיעבד בשוגג מותר, אבל במזיד קנסו ואסרו."},
  {id:"halacha-0044",q:"אין לי שני כיורים. מותר לשטוף כלי בשר ואחריהם כלי חלב באותה קערה?",options:["רק במים קרים","רק אם עברו 24 שעות","לא, צריך כיור נפרד בכל מקרה","כן, מותר"],answer:3,category:"halacha",difficulty:1,tags:["כשרות","מטבח"],note:"מותר להדיח בזה אחר זה באותה קערה, אפילו בחומרי ניקוי."},
  {id:"halacha-0045",q:"מעיקר הדין, צריך ספוג נפרד לכלים בשריים ולכלים חלביים?",options:["כן, זו חובה גמורה","רק לכלי זכוכית","לא, אבל רבים נוהגים לייחד ספוגים","רק בפסח"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","מטבח"],note:"מעיקר הדין אין צורך, ומנהג יפה לייחד."},
  {id:"halacha-0046",q:"מותר לכבס יחד מפות מארוחה בשרית ומארוחה חלבית?",options:["רק אם נוקו קודם ביד","כן, מותר","לא, צריך שתי מכונות","רק בכביסה קרה"],answer:1,category:"halacha",difficulty:1,tags:["כשרות","מטבח"],note:"אין לחשוש שיתבשלו השיירים יחד."},
  {id:"halacha-0047",q:"אפשר להשתמש באותו מדיח כלים לכלים בשריים ולחלביים, בזה אחר זה?",options:["רק בהפרש של שבוע","לא, אי אפשר בשום אופן","כן, אם מסירים קודם שיירים גדולים","רק לאחר הגעלה כל פעם"],answer:2,category:"halacha",difficulty:2,tags:["כשרות","מטבח"],note:"מותר אפילו באותו יום, כשלא מכניסים שיירי מאכל גדולים."},
  {id:"halacha-0048",q:"טוב לייחד צד אחד של השיש לבשרי וצד אחד לחלבי – זה מעיקר הדין?",options:["זה אסור, כי נראה כחומרה","לא, זה ראוי אך אינו מעיקר הדין","זה רק בשבת","כן, זו חובה"],answer:1,category:"halacha",difficulty:2,tags:["כשרות","מטבח"],note:"ראוי לעשות כן מחשש שיירים, אך אינו מעיקר הדין."},
  {id:"halacha-0049",q:"מסננת הכיור הבשרי התחלפה עם של הכיור החלבי. צריך להכשיר?",options:["לא, אין בכך כלום","כן, בליבון","צריך לזרוק אותן","כן, בהגעלה"],answer:0,category:"halacha",difficulty:2,tags:["כשרות","מטבח"],note:"המסנן שבפתח הניקוז אינו צריך הכשר."},
  {id:"halacha-0050",q:"מותר לשטוף כלים בסבון כלים שאין עליו הכשר?",options:["כן, ובלבד שישטפו היטב","לא, אסור","רק בכלי פלסטיק","רק בכלים חלביים"],answer:0,category:"halacha",difficulty:1,tags:["כשרות","מטבח"],note:"מותר, ונזהרים שלא יישאר סבון על הכלים."},
  {id:"halacha-0051",q:"מחבת שטיגנו בה בשמן דבר לא כשר. איך מכשירים אותה?",options:["בשטיפה בסבון","בהטבלה במקווה","בליבון","בהגעלה"],answer:2,category:"halacha",difficulty:3,tags:["כשרות","הגעלה"],note:"הגעלה אינה מועילה, וצריך ליבון."},
  {id:"halacha-0052",q:"מותר להגעיל יחד כלים בשריים וחלביים באותו סיר מים?",options:["לא, לעולם לא","רק כלים מאותו סוג","כן, אם עברו 24 שעות מהשימוש בהם","רק כלי זכוכית"],answer:2,category:"halacha",difficulty:3,tags:["כשרות","הגעלה"],note:"אחרי 24 שעות מותר אפילו לכתחילה."},
  {id:"halacha-0053",q:"בישלתי היום בשר בסיר. מותר לבשל בו אורז אחרי ניקוי ולהגיש אותו עם רוטב חלבי?",options:["לא, רק אחרי 24 שעות","לא, האורז נעשה בשרי","רק אם מוסיפים מים רבים","כן, מותר"],answer:3,category:"halacha",difficulty:2,tags:["כשרות","בשר וחלב"],note:"אחרי ניקוי היטב מותר באותו יום לבשל מאכל פרווה ולאכלו עם חלב."},
  {id:"halacha-0054",q:"חביתה שטוגנה במחבת בשרית נקייה – מותר לאכול אותה עם גבינה?",options:["כן, מותר","רק אחרי שש שעות","רק אם טוגנה בשמן זית","לא, היא בשרית"],answer:0,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"כשאין במחבת שיירי שומן בשר – מותר אפילו עם גבינה."},
  {id:"halacha-0055",q:"הסלט נשאר מהארוחה הבשרית. מתי אפשר להגיש אותו בארוחה חלבית?",options:["אף פעם","אם לקחו ממנו רק בכלי הגשה מיוחד לסלט","רק אחרי 24 שעות","בכל מקרה"],answer:1,category:"halacha",difficulty:2,tags:["כשרות","בשר וחלב"],note:"אם לקחו בכף או מזלג שאכלו בהם בשר – אין ראוי."},
  {id:"halacha-0056",q:"מותר לחתוך לחם בסכין בשרית נקייה ולאכול אותו עם גבינה?",options:["כן, מעיקר הדין מותר","רק אחרי שש שעות","רק לחם קלוי","לא, אסור"],answer:0,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"מותר כשהסכין נקייה, ויש מייחדים סכין ללחם."},
  {id:"halacha-0057",q:"פלטה בשרית נקייה – מותר לחמם עליה לחם לארוחה חלבית?",options:["רק בשבת","לא, הלחם נעשה בשרי","כן, אחרי ניקוי הפלטה","רק אם עטוף בנייר כסף"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","בשר וחלב"],note:"מותר אחרי ניקוי הפלטה."},
  {id:"halacha-0058",q:"לפי ההלכה, מה הבעיה באכילת דגים יחד עם בשר?",options:["חשש סכנה לבריאות","אין שום בעיה","בשר וחלב","חשש בישולי גויים"],answer:0,category:"halacha",difficulty:1,tags:["כשרות","דגים"],note:"אין לאכול בשר ודגים יחד משום סכנה (\"קשה לצרעת\")."},
  {id:"halacha-0059",q:"למנהג הספרדים, מה הדין באכילת דגים עם גבינה או חלב?",options:["מותר רק בשבת","יש להימנע, משום חשש סכנה","מותר לכתחילה","אסור מן התורה"],answer:1,category:"halacha",difficulty:2,tags:["כשרות","דגים"],note:"יוצאי אשכנז נוהגים להקל."},
  {id:"halacha-0060",q:"מותר לטגן דגים במחבת שטיגנו בה בשר באותו יום?",options:["כן, אחרי שטיפת המחבת","לא, רק אחרי 24 שעות","לא, לעולם לא","רק בשמן חדש ובמחבת אחרת"],answer:0,category:"halacha",difficulty:2,tags:["כשרות","דגים"],note:"מותר לאחר שטיפת המחבת."},
  {id:"halacha-0061",q:"מותר לצלות דגים ובשר זה ליד זה על רשת המנגל?",options:["רק אם הדג עטוף","רק בתנור","לא, אסור לגמרי","כן, אם אינם נוגעים זה בזה"],answer:3,category:"halacha",difficulty:2,tags:["כשרות","דגים","מנגל"],note:"על רשת פתוחה העשן מתפזר באוויר."},
  {id:"halacha-0062",q:"אפיתי בתנור ביתי דג ובשר באותה אפייה. מה דינם לפי הנפסק?",options:["שניהם מותרים","שניהם אסורים באכילה","רק הדג אסור","רק הבשר אסור"],answer:1,category:"halacha",difficulty:3,tags:["כשרות","דגים"],note:"בתנורי ימינו הם אסורים כי אין לאכול בשר עם דגים."},
  {id:"halacha-0063",q:"מצאתי כתם דם בחלמון של ביצה. מה הדין?",options:["מותרת רק בבישול","כל הביצה אסורה","מסירים את הדם ואוכלים","מותרת אחרי שטיפה"],answer:1,category:"halacha",difficulty:1,tags:["כשרות","ביצים"],note:"דם בחלמון אוסר את כל הביצה."},
  {id:"halacha-0064",q:"מצאתי כתם דם בחלבון של ביצה. מה הדין?",options:["זורקים את הדם ואוכלים את השאר","מותרת רק לבהמה","כל הביצה אסורה","צריך לזרוק גם את המחבת"],answer:0,category:"halacha",difficulty:1,tags:["כשרות","ביצים"],note:"דם בחלבון – זורקים את הדם ומשאירים את השאר."},
  {id:"halacha-0065",q:"צריך לבדוק ביצה קשה מבושלת אם יש בה דם?",options:["כן, תמיד","רק בביצת חופש","לא, אין צריך","רק בשבת"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","ביצים"],note:"רוב הביצים אין בהן דם."},
  {id:"halacha-0066",q:"מה נוהגים לעשות לפני שמטגנים ביצה במחבת?",options:["טובלים אותה במלח","שוטפים אותה במים חמים","בודקים אותה אם יש בה דם","מברכים עליה"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","ביצים"],note:"נהגו לבדוק ביצה לפני טיגון."},
  {id:"halacha-0067",q:"מצאתי ביצה עם שני חלמונים. מה הדין?",options:["צריך לשאול רב","מותרת באכילה","אסורה, חשש עוף טמא","מותרת רק בבישול"],answer:1,category:"halacha",difficulty:1,tags:["כשרות","ביצים"],note:"יש תרנגולות שמטילות ביצה כזו."},
  {id:"halacha-0068",q:"טרפתי שלוש ביצים בקערה ואז ראיתי דם בחלמון של אחת. מה הדין?",options:["הכל מותר אחרי סינון","מותר להשתמש לאפייה","כל הביצים אסורות","רק הביצה עם הדם אסורה"],answer:2,category:"halacha",difficulty:3,tags:["כשרות","ביצים"],note:"אחרי שנטרפו יחד, כשאין שישים – כולן אסורות."},
  {id:"halacha-0069",q:"צריך לבדוק תותים לפני אכילה?",options:["לא, אין בהם חרקים","רק תותים קפואים","רק בקיץ","כן, בדיקה ושטיפה היטב"],answer:3,category:"halacha",difficulty:1,tags:["כשרות","חרקים"],note:"אין לאכול תותים בלי בדיקה ושטיפה."},
  {id:"halacha-0070",q:"איפה בודקים תמרים לפני אכילה?",options:["אין צורך לבדוק","בטבילה במים","פותחים ובודקים ליד הגרעין","בקליפה החיצונית בלבד"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","חרקים"],note:"בתמרים מצויים תולעים ליד הגרעין."},
  {id:"halacha-0071",q:"מצאתי תולעת אחת בתבשיל ירקות. מה הדין?",options:["מותר רק אחרי סינון","כל התבשיל אסור","צריך להגעיל את הסיר","זורקים אותה ואוכלים את התבשיל"],answer:3,category:"halacha",difficulty:2,tags:["כשרות","חרקים"],note:"אחת או שתיים – משליכים; משלוש ומעלה התבשיל הוחזק בתולעים."},
  {id:"halacha-0072",q:"מכמה תולעים שנמצאו בתבשיל הוא נחשב \"מוחזק בתולעים\" ואסור?",options:["1","2","3","10"],answer:2,category:"halacha",difficulty:2,tags:["כשרות","חרקים"],note:"שלוש תולעים או יותר אוסרות את התבשיל."},
  {id:"halacha-0073",q:"מצאתי תולעת בשזיף. צריך לזרוק את כל הפרי?",options:["רק אם הוא יבש","לא, זורקים את התולעת ואוכלים את הפרי","צריך לזרוק את כל הקופסה","כן, כל הפרי אסור"],answer:1,category:"halacha",difficulty:1,tags:["כשרות","חרקים"],note:"הפרי עצמו אינו נאסר בגלל התולעת."},
  {id:"halacha-0074",q:"איך אוכלים תירס בלי חשש חרקים?",options:["אין בתירס חרקים","מבשלים היטב ואוכלים מהקלח","מפרידים את הגרעינים מהקלח ובודקים","שוטפים את הקלח במים"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","חרקים"],note:"התולעים נשארים בין הגרעינים גם אחרי בישול."},
  {id:"halacha-0075",q:"צריך לבדוק אורז לפני הבישול?",options:["רק אורז מלא","כן, גרגר אחר גרגר על דף","רק בפסח","לא, אורז אינו מתליע"],answer:1,category:"halacha",difficulty:1,tags:["כשרות","חרקים"],note:"אורז דרכו להתליע אחרי הקטיף."},
  {id:"halacha-0076",q:"צריך לבדוק כל בוטן ושקד מחרקים?",options:["רק קלויים","רק בחו\"ל","כן, כל אחד ואחד","לא, אין מצויים בהם הרבה"],answer:3,category:"halacha",difficulty:2,tags:["כשרות","חרקים"],note:"בבוטנים, שקדים, פיסטוקים וגרעינים אין צורך לבדוק כל אחד."},
  {id:"halacha-0077",q:"כיצד מומלץ להוסיף עלי נענע טריים לתה?",options:["ישירות לכוס החמה","אחרי שטיפה קצרה","רק עם סוכר","בתוך מסננת או אחרי ייבוש של שנה"],answer:3,category:"halacha",difficulty:3,tags:["כשרות","חרקים"],note:"כדי שהחרקים לא ירדו לכוס."},
  {id:"halacha-0078",q:"זיתים מקופסת שימורים שעברו עליהם שנים עשר חודש – צריך לבדוק?",options:["רק זיתים שחורים","רק זיתים מגולענים","לא, מותר בלי בדיקה","כן, כל זית"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","חרקים"],note:"אחרי שנים עשר חודש בשימורים – אין צורך."},
  {id:"halacha-0079",q:"פטרוזיליה ושמיר מיובשים בהשגחה מוכרת – צריך לבדוק?",options:["כן, כל עלה","לא, הקלייה הופכת את החרקים לאפר","רק לפני פסח","רק אם קונים בשוק"],answer:1,category:"halacha",difficulty:2,tags:["כשרות","חרקים"],note:"השריפה בתנורים מבטלת את חשש התולעים."},
  {id:"halacha-0080",q:"לפי הנפסק, מה הדרך הטובה ביותר בעלי חסה רגילים (שלא מגידול מיוחד)?",options:["לאכול כמו שהם","לבשל אותם","לאכול אחרי שטיפה קלה","להימנע מהם, כי הבדיקה קשה מאוד"],answer:3,category:"halacha",difficulty:2,tags:["כשרות","חרקים"],note:"מי שיראת ה' נוגעת ללבו יתרחק מהם."},
  {id:"halacha-0081",q:"עלי חסה מגידול מיוחד (עלי קטיף) – מה עושים לפני אכילה?",options:["אוכלים בלי שום בדיקה","חייבים להשרות יממה","אי אפשר לאכול אותם","בדיקה קלה ושטיפה בברז"],answer:3,category:"halacha",difficulty:2,tags:["כשרות","חרקים"],note:"גם בהם בודקים בדיקה רגילה ושוטפים."},
  {id:"halacha-0082",q:"מי נאמן על בדיקת ירקות מחרקים?",options:["רק רב או משגיח","כל מבוגר כשר ומדקדק במצוות","רק מי שבדק ליד עדים","רק בעל הבית עצמו"],answer:1,category:"halacha",difficulty:2,tags:["כשרות","חרקים"],note:"איש מעל 13 ואשה מעל 12 שמדקדקים – נאמנים."},
  {id:"halacha-0083",q:"מה נחשב \"בישולי גויים\" האסורים?",options:["רק מאכלים מטוגנים","כל מאכל שגוי נגע בו","מאכל שאינו נאכל חי ועולה על שולחן מלכים","רק בשר שגוי בישל"],answer:2,category:"halacha",difficulty:2,tags:["כשרות","בישולי גויים"],note:"כגון אורז ובשר שהגוי הניח על האש."},
  {id:"halacha-0084",q:"יהודי הדליק את האש, והעובדת הגויה הניחה עליה את הסיר. מה דין התבשיל?",options:["מותר בדיעבד בלבד","מותר רק לילדים","מותר, כי היהודי הדליק","אסור משום בישולי גויים"],answer:3,category:"halacha",difficulty:3,tags:["כשרות","בישולי גויים"],note:"הדלקת האש בידי יהודי מועילה רק בפת ולא בבישול."},
  {id:"halacha-0085",q:"עובד זר בישל אורז במסעדה של יהודי. מה דין האורז?",options:["מותר כי זה בבית יהודי","מותר אם יש משגיח בעיר","מותר אם הבשר כשר","אסור משום בישולי גויים"],answer:3,category:"halacha",difficulty:2,tags:["כשרות","בישולי גויים"],note:"גם בבית או במסעדה של ישראל יש דין בישולי גויים."},
  {id:"halacha-0086",q:"מותר לשתות קפה שהכין גוי?",options:["לא, זה בישולי גויים","רק קפה שחור","כן, וכך פשט המנהג","רק בחו\"ל"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","בישולי גויים"],note:"אין בקפה משום בישולי גויים, והמחמיר תבוא עליו ברכה."},
  {id:"halacha-0087",q:"חומוס קלוי ופיצוחים שקלה גוי – יש בהם בישולי גויים?",options:["רק אם קלויים בשמן","רק אם נמכרו בשבת","כן, הם אסורים","לא, אין מזמינים לסעודה על קליות"],answer:3,category:"halacha",difficulty:3,tags:["כשרות","בישולי גויים"],note:"קליות אינן עולות על שולחן מלכים."},
  {id:"halacha-0088",q:"מלפפונים חמוצים שהכין גוי במי מלח – מה הדין לגבי בישולי גויים?",options:["מותרים רק אחרי שטיפה","מותרים, כי לא בושלו באש","אסורים","מותרים רק בהכשר"],answer:1,category:"halacha",difficulty:2,tags:["כשרות","בישולי גויים"],note:"בישולי גויים נאסרו רק בבישול באש."},
  {id:"halacha-0089",q:"העובדת הגויה התחילה לבשל מרק, ולפני שהיה ראוי לאכילה הבישול הושלם בידי יהודי. מה הדין?",options:["מותר רק לגוי","אסור","מותר, אין בזה בישולי גויים","מותר רק בשבת"],answer:2,category:"halacha",difficulty:3,tags:["כשרות","בישולי גויים"],note:"כשהיהודי הכשיר את המאכל לאכילה – אין בזה בישולי גויים."},
  {id:"halacha-0090",q:"העובדת הגויה בישלה לעצמה בסירים של המשפחה. מה צריך לעשות?",options:["לזרוק אותם","אין צורך בכלום","להטביל אותם במקווה","להכשיר אותם בהגעלה"],answer:3,category:"halacha",difficulty:3,tags:["כשרות","בישולי גויים"],note:"הכלים בלעו טעם בישולי גויים וצריכים הגעלה."},
  {id:"halacha-0091",q:"לחם שאפה גוי בביתו (פת בעל הבית) – מה דינו?",options:["מותר בשעת הדחק","אסור","מותר אם יהודי חיממו","מותר בהכשר"],answer:1,category:"halacha",difficulty:2,tags:["כשרות","פת עכו\"ם"],note:"פת בעל הבית אסורה, ואפילו אם ישראל חזר ואפה אותה."},
  {id:"halacha-0092",q:"למה אסרו חכמים פת ובישולי גויים?",options:["כדי למנוע התקרבות וחתנות","בגלל מחירם","בגלל חשש גזל","בגלל חשש טומאה"],answer:0,category:"halacha",difficulty:2,tags:["כשרות","פת עכו\"ם"],note:"הטעם הוא \"משום חתנות\"."},
  {id:"halacha-0093",q:"לפי הנפסק לספרדים, מה הדין בשתיית חלב עכו\"ם (שחלבו גויים בלי השגחה)?",options:["מותר רק בחו\"ל","מותר לכתחילה","ראוי ונכון להחמיר","אסור מן התורה"],answer:2,category:"halacha",difficulty:2,tags:["כשרות","חלב"],note:"ראוי להחמיר, חוץ ממקום חולי או לתינוקות."},
  {id:"halacha-0094",q:"שוקולד כשר שיש בו אבקת חלב נכרי – מה הדין מעיקר הדין?",options:["מותר רק בפסח","מותר, אך ראוי להחמיר","אסור לגמרי","מותר רק לילדים"],answer:1,category:"halacha",difficulty:3,tags:["כשרות","חלב"],note:"מעיקר הדין אין בו איסור חלב עכו\"ם, ולקטנים מקלים."},
  {id:"halacha-0095",q:"בטיול בחו\"ל – מותר לקנות גבינה בלי הכשר בגלל שהיום לא מעמידים בקיבה?",options:["כן, אין בעיה","רק גבינה צהובה","רק בארץ","לא, גבינות גויים אסורות גם היום"],answer:3,category:"halacha",difficulty:2,tags:["כשרות","חו\"ל"],note:"זה דבר שנאסר במניין, ולכן קונים רק עם הכשר."},
  {id:"halacha-0096",q:"מה פירוש החותמת \"חלק\" על בשר?",options:["שהבשר רך במיוחד","שהבשר בלי שומן","שהבשר נשחט בארץ","שהבהמה לא נמצאה בה סירכא בריאה"],answer:3,category:"halacha",difficulty:1,tags:["כשרות","בשר"],note:"מנהג הספרדים לאכול רק בשר חלק."},
  {id:"halacha-0097",q:"קניתי סיר מתכת חדש מחנות של גוי. מה צריך לפני השימוש?",options:["ללבן אותו באש","אין צורך בכלום","להטביל אותו במקווה","לשטוף אותו ברותחים"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","טבילת כלים"],note:"כלי סעודה שנקנו מגוי טעונים טבילה."},
  {id:"halacha-0098",q:"איזה מהכלים הבאים חייב בטבילה?",options:["כוס נייר","מגש ניילון","כוס זכוכית","צלחת פלסטיק"],answer:2,category:"halacha",difficulty:1,tags:["כשרות","טבילת כלים"],note:"כלי מתכת וזכוכית חייבים; חרס, פלסטיק, ניילון ופורצלן פטורים."},
  {id:"halacha-0099",q:"איזה מהכלים הבאים פטור מטבילה?",options:["צלחת פלסטיק","כוס זכוכית","סכין פלדה","מחבת מתכת"],answer:0,category:"halacha",difficulty:1,tags:["כשרות","טבילת כלים"],note:"פלסטיק פטור מטבילה."},
  {id:"halacha-0100",q:"מה מברכים כשמטבילים כלי אחד בלבד?",options:["שהחיינו","אין מברכים","על טבילת כלים","על טבילת כלי"],answer:3,category:"halacha",difficulty:2,tags:["כשרות","טבילת כלים"],note:"על שני כלים או יותר מברכים \"על טבילת כלים\"."},
  {id:"halacha-0101",q:"יש לי כלי שספק אם הוא חייב בטבילה. מה עושים?",options:["לא מטבילים כלל","מטבילים עם כלי שחייב ודאי ומברכים","מטבילים פעמיים","מטבילים ומברכים עליו לבד"],answer:1,category:"halacha",difficulty:3,tags:["כשרות","טבילת כלים"],note:"ואם אין כלי ודאי – מטבילים בלי ברכה."},
  {id:"halacha-0102",q:"יש חלודה על כלי חדש שאני רוצה להטביל. מה עושים?",options:["מטבילים כמו שהוא","מנקים את החלודה לפני הטבילה","מטבילים פעמיים","לא מטבילים כלל"],answer:1,category:"halacha",difficulty:1,tags:["כשרות","טבילת כלים"],note:"אסור שתהיה חציצה בין הכלי למים."},
  {id:"halacha-0103",q:"איך מתמודדים עם קומקום חשמלי שיתקלקל בטבילה?",options:["מנגבים אותו במטלית לחה","מטבילים רק את המכסה","נותנים אותו במתנה לגוי ושואלים ממנו בחזרה","משתמשים בו בלי טבילה"],answer:2,category:"halacha",difficulty:3,tags:["כשרות","טבילת כלים"],note:"השואל כלי מגוי פטור מטבילה."},
  {id:"halacha-0104",q:"מותר לאכול במסעדה כשרה אם ידוע שהכלים שם לא הוטבלו?",options:["לא, אסור","כן, מותר","רק בכלים חד פעמיים","רק בחו\"ל"],answer:1,category:"halacha",difficulty:1,tags:["כשרות","טבילת כלים"],note:"מותר לאכול בקיוסק, מסעדה, בית הארחה ובמטוס."},
  {id:"halacha-0105",q:"אני מתארח אצל חבר שלא הטביל את הכלים שלו. מה הדין?",options:["צריך להגעיל את הכלים","גם האוכל אסור","מותר להשתמש בכלים","לא אשתמש בכלים, אבל האוכל עצמו אינו נאסר"],answer:3,category:"halacha",difficulty:2,tags:["כשרות","טבילת כלים"],note:"המאכל שבכלי אינו נאסר."},
  {id:"halacha-0106",q:"למה לכתחילה אין לבקש מגוי להטביל את הכלים?",options:["כי הוא יקלקל אותם","כי הכלים ייאסרו","כי זה אסור מן התורה","כי אין לגוי שליחות לברכה"],answer:3,category:"halacha",difficulty:3,tags:["כשרות","טבילת כלים"],note:"בדיעבד עלתה להם טבילה."},
  {id:"halacha-0107",q:"אפשר לשלוח ילד קטן לבדו להטביל כלי מתכת?",options:["לא, טבילתם מן התורה ואין מאמינים לקטן","רק כלי זכוכית","כן, בלי בעיה","כן, אם הוא מעל גיל שש"],answer:0,category:"halacha",difficulty:2,tags:["כשרות","טבילת כלים"],note:"מותר שיטביל בפני ישראל גדול."},
  {id:"halacha-0108",q:"איך מחזיקים את הכלי בשעת הטבילה?",options:["ביד קפוצה חזק","בחצאים, צד אחר צד","ביד רפויה, וכל הכלי בבת אחת","בכפפה"],answer:2,category:"halacha",difficulty:2,tags:["כשרות","טבילת כלים"],note:"אין טבילה לחצאין."},
  {id:"halacha-0109",q:"מטחנת קפה ידנית שטוחנים בה רק קפה – צריכה טבילה?",options:["לא","כן, בברכה","כן, בלי ברכה","רק אם היא ממתכת"],answer:0,category:"halacha",difficulty:3,tags:["כשרות","טבילת כלים"],note:"הקפה עוד צריך בישול, ולכן אינה צריכה טבילה."},
  {id:"halacha-0110",q:"כלי חרס המצופה זכוכית רק מבפנים – איך מטבילים?",options:["בברכה","לא מטבילים","פעמיים בברכה","בלי ברכה"],answer:3,category:"halacha",difficulty:3,tags:["כשרות","טבילת כלים"],note:"מצופה מבפנים ומבחוץ – טובלים בברכה."},
  {id:"halacha-0111",q:"קניתי כלי שיוצר במפעל של יהודים, בחנות של גוי. צריך להטביל?",options:["לא","רק בלי ברכה","כן","רק אם הוא מזכוכית"],answer:2,category:"halacha",difficulty:3,tags:["כשרות","טבילת כלים"],note:"הכלי עבר לרשות הגוי ויצא ממנה לרשות יהודי."},
  {id:"halacha-0112",q:"כלי האוכל של בית מלון – איך מטבילים אותם?",options:["רק בידי גוי","בברכה","הם פטורים לגמרי","בלי ברכה"],answer:3,category:"halacha",difficulty:3,tags:["כשרות","טבילת כלים"],note:"כלי סעודה של בתי מלון מטבילים בלי ברכה."},
  {id:"halacha-0113",q:"מותר לאכול במטוס מכלים שלא הוטבלו?",options:["רק משקאות","כן, מותר","לא","רק בטיסה של חברה ישראלית"],answer:1,category:"halacha",difficulty:3,tags:["כשרות","טבילת כלים","נסיעות"],note:"הכלים שבמטוס נכללים בהיתר."},
  {id:"halacha-0114",q:"איפה מברכים כשמטבילים כלים במקווה ציבורי?",options:["בתוך המים","אחרי הטבילה","מחוץ לחדר, וממהרים להטביל מיד","אין מברכים במקווה ציבורי"],answer:2,category:"halacha",difficulty:2,tags:["כשרות","טבילת כלים"],note:"מברכים לפני הטבילה."},
  {id:"halacha-0115",q:"מה מברכים על הפרשת חלה?",options:["המוציא לחם מן הארץ","שהחיינו","להפריש חלה תרומה","על הפרשת חלה"],answer:2,category:"halacha",difficulty:1,tags:["חלה","מצוות"],note:"הנוסח: \"אשר קדשנו במצוותיו וציונו להפריש חלה תרומה\"."},
  {id:"halacha-0116",q:"מה עושים היום עם החתיכה שהופרשה לחלה?",options:["קוברים אותה בגינה","שורפים אותה","נותנים לכהן לאכול","אופים אותה עם הבצק"],answer:1,category:"halacha",difficulty:1,tags:["חלה","מצוות"],note:"בזמן הזה שורפים את החלה, ולא מסתפקים בזריקה לפח."},
  {id:"halacha-0117",q:"מאיזו כמות קמח מפרישים חלה בברכה?",options:["1.56 ק\"ג","0.5 ק\"ג","1 ק\"ג","2.5 ק\"ג"],answer:0,category:"halacha",difficulty:2,tags:["חלה","שיעורים"],note:"1,560 גרם קמח ומעלה; פחות מזה – בלי ברכה או פטור."},
  {id:"halacha-0118",q:"מה אומרים אחרי שמפרישים את חתיכת הבצק?",options:["זה לכהן","אמן","ברוך שם כבוד מלכותו","הרי זו חלה"],answer:3,category:"halacha",difficulty:1,tags:["חלה","מצוות"],note:"מפרישים חתיכה קטנה ואומרים \"הרי זו חלה\"."},
  {id:"halacha-0119",q:"כמה בצק צריך להפריש לחלה בזמן הזה?",options:["עשירית מהבצק","חתיכה קטנה כל שהיא","אחד מ־24","אחד מ־48"],answer:1,category:"halacha",difficulty:2,tags:["חלה","מצוות"],note:"כיוון שהחלה נשרפת, די בכל שהוא."},
  {id:"halacha-0120",q:"שכחתי להפריש חלה ואפיתי את הלחמים. מה עושים?",options:["מפרישים בלי ברכה רק בשבת","אי אפשר יותר להפריש","צריך לזרוק את הלחמים","מפרישים מהלחם האפוי בברכה"],answer:3,category:"halacha",difficulty:1,tags:["חלה","מצוות"],note:"מכניסים את הלחמים לכלי אחד או מכסים במפה, ומפרישים."},
  {id:"halacha-0121",q:"אישה רוצה להפריש חלה מבצק שלה. צריכה רשות מבעלה?",options:["רק אם הקמח שלו","רק בפעם הראשונה","לא, היא קודמת לו במצווה זו","כן, תמיד"],answer:2,category:"halacha",difficulty:2,tags:["חלה","נשים"],note:"אין צורך ברשות, והיא אף יכולה למנות שליח."},
  {id:"halacha-0122",q:"למה יש מצווה ללוש ביום שישי עיסה גדולה?",options:["כדי להפריש ממנה חלה בברכה","כדי שיהיה לחם לכל השבוע","כדי לחסוך בגז","כדי לחלק לשכנים"],answer:0,category:"halacha",difficulty:2,tags:["חלה","שבת"],note:"מצווה גדולה ללוש בערב שבת בשיעור החייב בחלה."},
  {id:"halacha-0123",q:"מותר לומר \"מודה אני\" לפני נטילת ידיים בבוקר?",options:["כן, מיד כשמתעוררים","לא, רק אחרי נטילה","רק אחרי ברכות השחר","רק אחרי שמתלבשים"],answer:0,category:"halacha",difficulty:1,tags:["השכמה","מודה אני"],note:"אין בו שם ה', ולכן אומרים אותו מיד כשמתעוררים."},
  {id:"halacha-0124",q:"כמה פעמים שופכים מים על כל יד בנטילת ידיים של הבוקר?",options:["1","2","3","7"],answer:2,category:"halacha",difficulty:1,tags:["נטילת ידיים","השכמה"],note:"שלוש פעמים לסירוגין, ימין ושמאל חליפות."},
  {id:"halacha-0125",q:"באיזו יד מתחילים בנטילת ידיים של הבוקר?",options:["ימין","לא משנה","שמאל","ביד החזקה"],answer:0,category:"halacha",difficulty:1,tags:["נטילת ידיים","השכמה"],note:"מקדימים יד ימין."},
  {id:"halacha-0126",q:"באיזה סדר שופכים בנטילת ידיים של שחרית?",options:["לסירוגין: ימין, שמאל וחוזר חלילה","שלוש פעמים רצופות על ימין ואז על שמאל","על שתי הידיים יחד","רק על יד ימין"],answer:0,category:"halacha",difficulty:2,tags:["נטילת ידיים","השכמה"],note:"לא שלוש פעמים רצופות על אותה יד."},
  {id:"halacha-0127",q:"מתי מברכים \"על נטילת ידיים\" בבוקר?",options:["אחרי התפילה","אחרי שמתלבשים","לפני שפותחים את הברז","לפני ניגוב הידיים"],answer:3,category:"halacha",difficulty:1,tags:["נטילת ידיים","השכמה"],note:"נוטלים ומברכים לפני הניגוב."},
  {id:"halacha-0128",q:"אין לי כלי לנטילה בבוקר. מה עושים?",options:["נוטלים מהברז שלוש פעמים, בלי ברכה","מחכים עד שיימצא כלי","לא נוטלים כלל","נוטלים מהברז ומברכים"],answer:0,category:"halacha",difficulty:2,tags:["נטילת ידיים","השכמה"],note:"נוטלים לסירוגין מהברז ואין מברכים \"על נטילת ידיים\"."},
  {id:"halacha-0129",q:"נשארתי ער כל הלילה. איך נוטלים ידיים בבוקר?",options:["נוטלים פעם אחת בלבד","נוטלים בלי ברכה","נוטלים בברכה","לא נוטלים כלל"],answer:1,category:"halacha",difficulty:2,tags:["נטילת ידיים","השכמה"],note:"יש ספק אם חייב, ולכן נוטל בלי ברכה."},
  {id:"halacha-0130",q:"ישנתי שינה ארוכה בצהריים. מה הדין בנטילת ידיים?",options:["אין צורך כלל","נוטלים שלוש פעמים בלי ברכה","נוטלים רק יד ימין","נוטלים בברכה"],answer:1,category:"halacha",difficulty:3,tags:["נטילת ידיים"],note:"הישן ביום (שיעור \"שיתין נשמי\") נוטל מספק בלי ברכה."},
  {id:"halacha-0131",q:"נשים חייבות בנטילת ידיים של שחרית ובברכה עליה?",options:["כן","רק בשבת","לא","רק נשים נשואות"],answer:0,category:"halacha",difficulty:1,tags:["נטילת ידיים","נשים"],note:"נשים חייבות ומברכות \"על נטילת ידיים\"."},
  {id:"halacha-0132",q:"מותר להתלבש לפני נטילת ידיים בבוקר?",options:["כן, מן הדין מותר","לא, אסור לגעת בבגדים","רק בגדים חדשים","רק בחורף"],answer:0,category:"halacha",difficulty:1,tags:["נטילת ידיים","השכמה"],note:"אין לחשוש לרוח רעה בנגיעה בבגדים."},
  {id:"halacha-0133",q:"גזזתי ציפורניים. צריך ליטול ידיים?",options:["רק בערב שבת","לא","כן","רק בגזיזת ציפורני ידיים"],answer:2,category:"halacha",difficulty:1,tags:["נטילת ידיים"],note:"גם בגזיזה חלקית וגם בציפורני הרגליים."},
  {id:"halacha-0134",q:"נגעתי בנעליים שלי. צריך ליטול ידיים?",options:["לא","כן","רק בנעלי עור","רק אם הן מלוכלכות"],answer:1,category:"halacha",difficulty:1,tags:["נטילת ידיים"],note:"גם בנעליים של אחרים; בגרביים נקיות – לא."},
  {id:"halacha-0135",q:"חזרתי מלוויה. מה עושים כשיוצאים מבית הקברות?",options:["נוטלים ידיים","מברכים שהחיינו","מחליפים בגדים מיד","מתקלחים מיד"],answer:0,category:"halacha",difficulty:1,tags:["נטילת ידיים","אבלות"],note:"היוצא מבית הקברות נוטל ידיו."},
  {id:"halacha-0136",q:"כמה פעמים נוטלים ידיים ביציאה מהשירותים, לפי המנהג?",options:["שלוש פעמים, בלי צורך בכלי","שבע פעמים","אין צורך ליטול","פעם אחת בכלי"],answer:0,category:"halacha",difficulty:3,tags:["נטילת ידיים"],note:"מעיקר הדין די בפעם אחת מהברז, ונהגו שלוש."},
  {id:"halacha-0137",q:"יצאתי מהמקלחת. איך נוטלים ידיים?",options:["אין צורך","שבע פעמים","שלוש פעמים בכלי ובברכה","פעם אחת, אפילו מהברז"],answer:3,category:"halacha",difficulty:3,tags:["נטילת ידיים"],note:"היוצא מאמבטיה נוטל פעם אחת."},
  {id:"halacha-0138",q:"בשירותים של המטוס הכיור נמצא בתוך התא. איך נוטלים ידיים?",options:["מנגבים בממחטה לחה","מכסים את מושב האסלה ונוטלים","לא נוטלים כלל","נוטלים מחוץ למטוס בלבד"],answer:1,category:"halacha",difficulty:3,tags:["נטילת ידיים","נסיעות"],note:"וכשמגיעים למחוז החפץ טוב ליטול שוב."},
  {id:"halacha-0139",q:"שכחתי לברך \"אשר יצר\". עד כמה זמן אפשר עוד לברך?",options:["72 דקות","עד הערב","10 דקות","30 דקות"],answer:0,category:"halacha",difficulty:2,tags:["אשר יצר"],note:"שיעור פרסה; אחרי זמן זה לא יברך."},
  {id:"halacha-0140",q:"בטיול רוצים לאכול כריך ואין מים לנטילה. מה עושים אם אין מים קרובים בדרך?",options:["אוכלים בלי שום דבר","מוותרים על האכילה","כורכים מפה על הידיים ואוכלים","מנגבים בחול"],answer:2,category:"halacha",difficulty:2,tags:["נטילת ידיים","נסיעות"],note:"אם יש מים בדרך בטווח ארבעה מילין – ממתינים."},
  {id:"halacha-0141",q:"מותר לברך ולהזכיר שם ה' בלי כיסוי ראש?",options:["לא","רק בברכות קצרות","רק בבית","כן"],answer:0,category:"halacha",difficulty:1,tags:["כיפה"],note:"אסור לברך בגילוי ראש."},
  {id:"halacha-0142",q:"הכיפה נפלה לי באמצע שמונה עשרה ולא הרגשתי עד הסוף. האם חוזרים?",options:["חוזרים במנחה","לא, בדיעבד יצא","כן, חוזרים לראש","חוזרים רק לברכה האחרונה"],answer:1,category:"halacha",difficulty:1,tags:["כיפה","תפילה"],note:"בדיעבד תפילתו תפילה."},
  {id:"halacha-0143",q:"מה הדין בכיפה קטנה?",options:["מותרת רק בבית","אסורה","מותרת רק לילדים","מותרת אם נראית היטב מכל צדי הראש"],answer:3,category:"halacha",difficulty:2,tags:["כיפה"],note:"בתפילה ובברכת המזון ראוי לכסות את רוב הראש."},
  {id:"halacha-0144",q:"מותר ללמוד תורה לבד בחדר בלי כיפה?",options:["מותר לכתחילה","יש להיזהר בזה מאוד","רק אם לומדים בעל פה","רק בלילה"],answer:1,category:"halacha",difficulty:2,tags:["כיפה","לימוד תורה"],note:"אף שאין זה מעיקר הדין, יש להיזהר מאוד."},
  {id:"halacha-0145",q:"לפי מנהג הספרדים, איפה הציציות של הטלית קטן?",options:["בחוץ, מעל המכנסיים","מכוסות תחת הבגדים","רק בצד ימין","אין מנהג קבוע"],answer:1,category:"halacha",difficulty:1,tags:["ציצית"],note:"כך ראוי גם על פי הקבלה; מנהג האשכנזים להוציאן."},
  {id:"halacha-0146",q:"לפי מנהג הספרדים, בחור רווק מתעטף בטלית גדול בשחרית?",options:["רק ביום כיפור","לא, רק אחרי החתונה","כן","רק בשבת"],answer:2,category:"halacha",difficulty:1,tags:["ציצית","טלית"],note:"בחורים שהגיעו למצוות מתעטפים בטלית גדול."},
  {id:"halacha-0147",q:"מה קודם בבוקר – טלית או תפילין?",options:["טלית","לא משנה","תלוי במנהג המשפחה","תפילין"],answer:0,category:"halacha",difficulty:1,tags:["ציצית","תפילין"],note:"\"מעלין בקודש\" – קודם ציצית ואחר כך תפילין."},
  {id:"halacha-0148",q:"נשים חייבות במצוות ציצית?",options:["רק נשואות","לא, הן פטורות","רק בשבת","כן"],answer:1,category:"halacha",difficulty:1,tags:["ציצית","נשים"],note:"ואין להן להתעטף אפילו בלי ברכה."},
  {id:"halacha-0149",q:"ישנתי עם הטלית קטן. מברכים עליו בבוקר?",options:["כן, בברכה נפרדת","לא, פוטרים אותו בברכת הטלית הגדול","מחליפים ומברכים","מברכים רק שהחיינו"],answer:1,category:"halacha",difficulty:2,tags:["ציצית"],note:"מכוונים בברכת הטלית הגדול לפטור גם את הקטן."},
  {id:"halacha-0150",q:"הטלית נפלה ממני לגמרי ואני מתעטף שוב. צריך לברך?",options:["רק בשבת","לא","כן","רק אם נפלה לרצפה"],answer:1,category:"halacha",difficulty:1,tags:["ציצית"],note:"אין צריך לחזור ולברך."},
  {id:"halacha-0151",q:"הורדתי את הטלית לשירותים. אחרי כמה זמן כבר צריך לברך שוב כשחוזרים?",options:["חמש דקות","שעה וחצי","חצי שעה","שלוש שעות"],answer:2,category:"halacha",difficulty:2,tags:["ציצית"],note:"פשט על דעת לחזור וחזר בתוך חצי שעה – אינו מברך."},
  {id:"halacha-0152",q:"מאיזו שעה לכתחילה מתעטפים בטלית בברכה?",options:["מהנץ החמה בלבד","משעה רביעית","מחצות הלילה","כשעה לפני הנץ"],answer:3,category:"halacha",difficulty:3,tags:["ציצית","זמנים"],note:"פועלים ממהרים רשאים כשש דקות אחרי עמוד השחר."},
  {id:"halacha-0153",q:"על איזה מהבאים מברכים \"שהחיינו\"?",options:["ציציות חדשות לטלית ישנה","טלית חדשה","גרביים חדשות","תפילין חדשות"],answer:1,category:"halacha",difficulty:2,tags:["ציצית","שהחיינו"],note:"על טלית חדשה מברכים; על תפילין חדשות לא."},
  {id:"halacha-0154",q:"מתי טוב להסיר את הטלית בסוף התפילה?",options:["אחרי קריאת שמע","לפני חליצת התפילין","מיד אחרי העמידה","אחרי \"עלינו לשבח\" ואחרי חליצת התפילין"],answer:3,category:"halacha",difficulty:2,tags:["ציצית","תפילה"],note:"אין להסיר את הטלית לפני התפילין."},
  {id:"halacha-0155",q:"בכמה כנפות בגד יש מצווה להטיל ציצית?",options:["2","3","4","6"],answer:2,category:"halacha",difficulty:1,tags:["ציצית"],note:"ציצית מוטלת בבגד בן ארבע כנפות."},
  {id:"halacha-0156",q:"מה מניחים קודם – תפילין של יד או של ראש?",options:["יחד","תלוי במנהג","של יד","של ראש"],answer:2,category:"halacha",difficulty:1,tags:["תפילין"],note:"ואם הקדים של ראש – אינו מסיר אותה, אלא מניח של יד."},
  {id:"halacha-0157",q:"לפי מנהג הספרדים, כמה ברכות מברכים על הנחת תפילין?",options:["1","2","3","4"],answer:0,category:"halacha",difficulty:1,tags:["תפילין"],note:"ברכה אחת, \"להניח תפילין\", ופוטרת גם את של ראש."},
  {id:"halacha-0158",q:"לפי מנהג הספרדים על פי הקבלה, איך מניחים תפילין?",options:["של ראש בישיבה ושל יד בעמידה","שתיהן בעמידה","של יד בישיבה ושל ראש בעמידה","שתיהן בישיבה"],answer:2,category:"halacha",difficulty:2,tags:["תפילין"],note:"מנהג האשכנזים להניח את שתיהן בעמידה."},
  {id:"halacha-0159",q:"דיברתי דברים שלא לצורך התפילין בין של יד לשל ראש. מה הדין?",options:["מברכים על של ראש \"על מצוות תפילין\"","מורידים את של יד","חוזרים ומניחים הכל מחדש","אין צריך לעשות כלום"],answer:0,category:"halacha",difficulty:3,tags:["תפילין"],note:"אם דיבר לצורך התפילין – אינו מברך שוב."},
  {id:"halacha-0160",q:"הנחתי תפילין ושכחתי לברך. מה עושים?",options:["מברכים רק למחרת","אי אפשר יותר לברך","מורידים ומניחים מחדש בברכה","ממשמשים בהן ומברכים כל עוד הן עליי"],answer:3,category:"halacha",difficulty:1,tags:["תפילין"],note:"כל זמן שהתפילין עליו – מברך."},
  {id:"halacha-0161",q:"איפה מניחים את התפילין של ראש?",options:["במקום שערות הראש, מכוון בין העיניים","על המצח","בצד הראש","על העורף"],answer:0,category:"halacha",difficulty:1,tags:["תפילין"],note:"אסור שיהיה אפילו חלק קטן מהן על המצח."},
  {id:"halacha-0162",q:"אני שמאלי – כותב ביד שמאל. על איזו יד אניח תפילין?",options:["על יד ימין","על יד שמאל","על שתיהן","לפי מה שנוח"],answer:0,category:"halacha",difficulty:2,tags:["תפילין"],note:"הולכים אחר היד שכותבים בה."},
  {id:"halacha-0163",q:"צריך להוריד את שעון היד לפני הנחת תפילין של יד?",options:["רק שעון מתכת","לא, מותר להשאיר אותו","רק בשבת","כן, חובה"],answer:1,category:"halacha",difficulty:1,tags:["תפילין"],note:"ברצועות אחרי שבע הכריכות אין דין חציצה; המחמיר תבוא עליו ברכה."},
  {id:"halacha-0164",q:"חלצתי תפילין כדי להיכנס לשירותים. כשאני חוזר ומניח – צריך לברך שוב?",options:["לא, אם היה פחות מחצי שעה","לא, אם התכוון לחזור","כן, אפילו אחרי זמן מועט","רק אם שהה שעה"],answer:2,category:"halacha",difficulty:2,tags:["תפילין"],note:"בתפילין, בשונה מטלית, חוזר ומברך."},
  {id:"halacha-0165",q:"עד מתי לכתחילה אפשר להניח תפילין?",options:["עד צאת הכוכבים","עד השקיעה","עד סוף זמן קריאת שמע","עד חצות היום"],answer:1,category:"halacha",difficulty:1,tags:["תפילין","זמנים"],note:"ובבין השמשות, עד 13.5 דקות, עוד אפשר להניח בברכה."},
  {id:"halacha-0166",q:"השמש שקעה לפני חמש דקות ולא הנחתי היום תפילין. מה עושים?",options:["מניחים בלי ברכה רק של יד","מניחים למחרת פעמיים","כבר אי אפשר להניח","מניחים מיד ואף מברכים"],answer:3,category:"halacha",difficulty:3,tags:["תפילין","זמנים"],note:"בבין השמשות (13.5 דקות) עוד מניחים בברכה."},
  {id:"halacha-0167",q:"לפי המנהג, מתי חולצים את התפילין בסוף שחרית ביום חול?",options:["מיד אחרי העמידה","לפני אשרי","לא לפני קדושת \"ובא לציון\"","לפני קריאת התורה"],answer:2,category:"halacha",difficulty:2,tags:["תפילין","תפילה"],note:"נהגו שלא לחלוץ לפחות עד אחרי \"ובא לציון\"."},
  {id:"halacha-0168",q:"מתי חולצים תפילין בראש חודש?",options:["לפני הלל","לא מניחים כלל בראש חודש","לפני מוסף, אחרי חצי קדיש","אחרי עלינו לשבח"],answer:2,category:"halacha",difficulty:3,tags:["תפילין","ראש חודש"],note:"חולצים לפני מוסף ולא לפני חצי הקדיש."},
  {id:"halacha-0169",q:"לפי המנהג הנפוץ בארץ ישראל, מניחים תפילין בחול המועד?",options:["רק בפסח","לא","רק בסוכות","כן"],answer:1,category:"halacha",difficulty:1,tags:["תפילין","מועדים"],note:"גם מי שנהג בחו\"ל להניח – בארץ נוהג כמנהג הארץ."},
  {id:"halacha-0170",q:"מותר לנמנם כשהתפילין עליי?",options:["כן, שינה קצרה","לא, אפילו שינת עראי","כן, בישיבה","רק בבית הכנסת"],answer:1,category:"halacha",difficulty:1,tags:["תפילין"],note:"כל זמן שהתפילין עליו אסור לישון בהן."},
  {id:"halacha-0171",q:"לפי מעיקר הדין, כל כמה זמן חובה לבדוק תפילין כשרות?",options:["אין חובה לבדוק","כל שבע שנים","כל שנה","כל שלוש שנים וחצי"],answer:0,category:"halacha",difficulty:2,tags:["תפילין"],note:"ממידת חסידות בודקים כל שנה באלול."},
  {id:"halacha-0172",q:"שכחתי להניח תפילין יום אחד. מה ראוי לעשות?",options:["תשובה, בדיקת התפילין וצדקה","אין צורך בדבר","לצום שלושה ימים","להניח פעמיים למחרת"],answer:0,category:"halacha",difficulty:2,tags:["תפילין"],note:"וטוב להשתדל להניח גם תפילין דרבנו תם."},
  {id:"halacha-0173",q:"טסתי מארה\"ב לארץ ובגלל קו התאריך כבר \"יום מחר\" לפני שהחשיך. צריך להניח תפילין שוב?",options:["רק אם הגעתי לארץ","לא, כבר הנחתי היום","רק של יד","כן, לפני שתחשך"],answer:3,category:"halacha",difficulty:3,tags:["תפילין","נסיעות"],note:"מה שהניח אתמול אינו פוטר את היום החדש."},
  {id:"halacha-0174",q:"אבל ביום הראשון לאבלות (יום הקבורה) – מניח תפילין?",options:["רק במנחה","לא","כן, אחרי הקבורה","רק של יד"],answer:1,category:"halacha",difficulty:1,tags:["תפילין","אבלות"],note:"וביום השני מניח אחרי הנץ החמה."},
  {id:"halacha-0175",q:"נשים רוצות להחמיר ולהניח תפילין. מה הנפסק?",options:["מותר בברכה","מוחים בידן","מותר בלי ברכה","חובה"],answer:1,category:"halacha",difficulty:2,tags:["תפילין","נשים"],note:"נשים פטורות מתפילין."},
  {id:"halacha-0176",q:"כמה פרשיות כתובות בתפילין?",options:["2","3","4","5"],answer:2,category:"halacha",difficulty:1,tags:["תפילין"],note:"ארבע פרשיות: קדש, והיה כי יביאך, שמע, והיה אם שמוע."},
  {id:"halacha-0177",q:"באיזה צד של הפתח קובעים את המזוזה?",options:["בצד שמאל של הנכנס","באמצע המשקוף","בצד הקרוב לחלון","בצד ימין של הנכנס"],answer:3,category:"halacha",difficulty:1,tags:["מזוזה"],note:"\"ביתך\" – דרך ביאתך, מימין."},
  {id:"halacha-0178",q:"לפי מנהג הספרדים, איך קובעים את המזוזה?",options:["באלכסון","שוכבת לרוחב","זקופה לאורך המשקוף","הפוכה"],answer:2,category:"halacha",difficulty:1,tags:["מזוזה"],note:"מזוזה שוכבת לרוחב הפתח פסולה."},
  {id:"halacha-0179",q:"באיזה גובה קובעים מזוזה?",options:["בדיוק באמצע הפתח","בחלק העליון ממש","בתחילת השליש העליון של גובה הפתח","בגובה העיניים תמיד"],answer:2,category:"halacha",difficulty:2,tags:["מזוזה"],note:"מחלקים את גובה הפתח לשלושה."},
  {id:"halacha-0180",q:"מה מברכים כשקובעים מזוזה?",options:["אין מברכים","על מצוות מזוזה","לקבוע מזוזה","שהחיינו"],answer:2,category:"halacha",difficulty:1,tags:["מזוזה"],note:"מברכים \"אשר קדשנו במצוותיו וצוונו לקבוע מזוזה\"."},
  {id:"halacha-0181",q:"לפי מעיקר הדין, כל כמה זמן חייבים לבדוק מזוזות בבית פרטי?",options:["כל שנה","פעמיים בשבע שנים","כל עשר שנים","פעם בחיים"],answer:1,category:"halacha",difficulty:3,tags:["מזוזה"],note:"פעם בשלוש שנים וחצי; ממידת חסידות – כל שנה באלול."},
  {id:"halacha-0182",q:"באיזה חודש נוהגים ממידת חסידות לבדוק מזוזות ותפילין?",options:["תשרי","אב","אלול","ניסן"],answer:2,category:"halacha",difficulty:1,tags:["מזוזה","תפילין"],note:"לקראת הימים הנוראים."},
  {id:"halacha-0183",q:"צריך מזוזה בפתח חדר האמבטיה והשירותים?",options:["רק במלון","כן, בלי ברכה","לא, הם פטורים","כן, בברכה"],answer:2,category:"halacha",difficulty:1,tags:["מזוזה"],note:"אינם דירת כבוד."},
  {id:"halacha-0184",q:"צריך מזוזה בפתח המטבח?",options:["כן","לא","רק אם אוכלים בו","רק במטבח גדול"],answer:0,category:"halacha",difficulty:1,tags:["מזוזה"],note:"מטבח חייב במזוזה בכל מקרה."},
  {id:"halacha-0185",q:"שוכר דירה בארץ ישראל – מתי חייב לקבוע מזוזה?",options:["אחרי שלושים יום","רק אם שוכר לשנה","בעל הבית חייב, לא השוכר","מיד, בברכה"],answer:3,category:"halacha",difficulty:2,tags:["מזוזה","ארץ ישראל"],note:"משום יישוב ארץ ישראל; בחו\"ל – פטור שלושים יום."},
  {id:"halacha-0186",q:"שוכר דירה בחוץ לארץ – כמה ימים הוא פטור ממזוזה?",options:["7","12","30","90"],answer:2,category:"halacha",difficulty:3,tags:["מזוזה","חו\"ל"],note:"בארץ ישראל חייב מיד."},
  {id:"halacha-0187",q:"אני קובע מזוזות בכל חדרי הבית. כמה פעמים מברכים?",options:["לא מברכים כלל","על כל מזוזה","פעם אחת, על המזוזה הראשונה","על כל שתי מזוזות"],answer:2,category:"halacha",difficulty:1,tags:["מזוזה"],note:"ברכה על כל מזוזה היא ברכה שאינה צריכה."},
  {id:"halacha-0188",q:"עברתי לדירה שכבר יש בה מזוזות. מה ראוי לעשות?",options:["להחליף בחדשות בלי ברכה","לקבוע עוד מזוזה ליד כל אחת","להסיר, לבדוק ולחזור לקבוע בברכה","להשאיר ולא לבדוק"],answer:2,category:"halacha",difficulty:2,tags:["מזוזה"],note:"כך נוהגים הנכנסים לדירה."},
  {id:"halacha-0189",q:"מתי קובעים מזוזה בדירה חדשה?",options:["רק בחנוכת הבית","רק בראש חודש","שלושים יום אחרי הכניסה","כשנכנסים לגור, עם הכנסת חלק מהחפצים"],answer:3,category:"halacha",difficulty:2,tags:["מזוזה"],note:"מזוזה היא חובת הדר, ולא דוחים אותה למסיבה."},
  {id:"halacha-0190",q:"צריך מזוזה ברכב או באוטובוס?",options:["לא, הם פטורים","כן, בברכה","רק ברכב חדש","כן, בלי ברכה"],answer:0,category:"halacha",difficulty:1,tags:["מזוזה","נסיעות"],note:"אינם לדירת קבע; גם קרון נגרר פטור."},
  {id:"halacha-0191",q:"חדר קטן שאין בו ארבע אמות על ארבע אמות – מה דינו לגבי מזוזה?",options:["פטור","חייב רק אם יש בו חלון","חייב בברכה","חייב רק בפתח הראשי"],answer:0,category:"halacha",difficulty:2,tags:["מזוזה"],note:"ארבע אמות הן כ־1.96 מטר."},
  {id:"halacha-0192",q:"נשים חייבות במצוות מזוזה?",options:["כן","לא","רק נשואות","רק בבית שלהן"],answer:0,category:"halacha",difficulty:1,tags:["מזוזה","נשים"],note:"\"למען ירבו ימיכם\" – גם הנשים צריכות לחיים."},
  {id:"halacha-0193",q:"המזוזה נפלה לי מהיד על הרצפה. האם צריך לצום?",options:["כן, יום אחד","כן, שלושה ימים","לא, טוב לתת צדקה","צריך לגנוז אותה"],answer:2,category:"halacha",difficulty:1,tags:["מזוזה"],note:"ונכון גם לבדוק את שאר מזוזות הבית."},
  {id:"halacha-0194",q:"צבעו את הבית בלי להוריד את המזוזות. מה צריך לעשות?",options:["אין צורך בכלום","להחליף אותן","לבדוק אותן","לקבוע אותן מחדש בברכה"],answer:2,category:"halacha",difficulty:1,tags:["מזוזה"],note:"ייתכן שנכנסה לחות והאותיות התקלקלו."},
  {id:"halacha-0195",q:"המזוזה נפלה מהפתח ואני מחזיר אותה. מברכים שוב?",options:["רק אם נפלה בלילה","רק אם עבר שבוע","לא, ספק ברכות להקל","כן"],answer:2,category:"halacha",difficulty:3,tags:["מזוזה","ספק ברכות"],note:"יש בזה מחלוקת, ולכן אין מברכים."},
  {id:"halacha-0196",q:"המשקוף מברזל. מותר להדביק את המזוזה בדבק?",options:["רק אם תלויה בחוט","לא, חובה במסמרים","רק בסלוטייפ","כן, בדבק חזק ויציב"],answer:3,category:"halacha",difficulty:2,tags:["מזוזה"],note:"מזוזה תלויה ומתנדנדת – פסולה."},
  {id:"halacha-0197",q:"חזרנו מחודש בחו\"ל. צריך לברך שוב על המזוזות?",options:["כן, על הראשונה","רק אם הבית היה מושכר","לא","כן, על כולן"],answer:2,category:"halacha",difficulty:1,tags:["מזוזה"],note:"הבית לא יצא מחיוב מזוזה."},
  {id:"halacha-0198",q:"משרד או קופת חולים – מה דינם במזוזה?",options:["רק אם ישנים שם","חייבים, והקובע בלי ברכה יש לו על מי לסמוך","פטורים לגמרי","חייבים בברכה בכל מקרה"],answer:1,category:"halacha",difficulty:3,tags:["מזוזה"],note:"חייבים אף שאין בהם דירה."},
  {id:"halacha-0199",q:"מה המנהג לגבי מזוזה במעלית?",options:["חייבת רק בבניין חדש","אסור לקבוע בה","חייבת בברכה","המעלית פטורה, והמחמיר קובע בלי ברכה"],answer:3,category:"halacha",difficulty:3,tags:["מזוזה"],note:"המנהג כדעת האומרים שמעלית פטורה."},
  {id:"halacha-0200",q:"מה יש נוהגים לומר בנשיקת המזוזה ביציאה מהבית?",options:["לשנה הבאה בירושלים","שמע ישראל","ה' ישמור צאתי ובואי","ברוך הבא"],answer:2,category:"halacha",difficulty:2,tags:["מזוזה","מנהגים"],note:"\"...אל שדי יברך אותי ויתן לי רחמים\"."},
  {id:"halacha-0201",q:"עושים סעודת חנוכת הבית גם בדירה שכורה?",options:["רק בבית פרטי","כן, ראוי","רק אחרי שנה","לא, רק בדירה שנקנתה"],answer:1,category:"halacha",difficulty:1,tags:["חנוכת הבית"],note:"ראוי לעשות גם כששוכרים."},
  {id:"halacha-0202",q:"מדוע אין עורכים חנוכת בית בין י\"ז בתמוז לתשעה באב?",options:["כי אסור לקבוע מזוזה","כי זה זמן תענית","כי אין מברכים שהחיינו בימים אלה","כי אסור לעבור דירה"],answer:2,category:"halacha",difficulty:2,tags:["חנוכת הבית","בין המצרים"],note:"נוהגים שלא לברך שהחיינו בימים אלו."},
  {id:"halacha-0203",q:"אבא נכנס לחדר. מתי צריך לקום לכבודו?",options:["רק בפעם הראשונה ביום","רק כשיש אורחים","רק כשהוא מגיע לידי","מרגע שרואים אותו"],answer:3,category:"halacha",difficulty:1,tags:["כיבוד הורים"],note:"חייבים לקום מלוא עיניו, ובכל פעם, אפילו מאה פעמים ביום."},
  {id:"halacha-0204",q:"כמה פעמים ביום צריך לקום כשההורים נכנסים לחדר?",options:["בכל פעם שנכנסים","רק בפעם הראשונה","פעמיים ביום","רק בשבת"],answer:0,category:"halacha",difficulty:1,tags:["כיבוד הורים"],note:"אפילו מאה פעמים ביום, וגם כשהוא לבד איתם."},
  {id:"halacha-0205",q:"מותר לשבת במקום הקבוע של אבא ליד השולחן?",options:["לא","כן, אם הוא לא בבית","רק בשבת","כן, אם אין מקום אחר"],answer:0,category:"halacha",difficulty:1,tags:["כיבוד הורים","מורא"],note:"לעמוד שם מותר, לשבת – לא."},
  {id:"halacha-0206",q:"מותר לקרוא להורים בשמם הפרטי?",options:["רק בבית","רק כשהם לא שומעים","לא, זה זלזול בכבודם","כן, אם הם מסכימים"],answer:2,category:"halacha",difficulty:1,tags:["כיבוד הורים","מורא"],note:"במקומותינו מקפידים שלא לקרוא לאב בשמו."},
  {id:"halacha-0207",q:"ההורים עלו לאוטובוס ואני יושב. מה עושים?",options:["נשארים לשבת","קמים, ואם אין להם מקום מפנים להם","קמים רק לאמא","מציעים רק אם הם מבקשים"],answer:1,category:"halacha",difficulty:1,tags:["כיבוד הורים"],note:"אסור לשבת לפניהם כשהם עומדים."},
  {id:"halacha-0208",q:"על חשבון מי מפרנסים הורים שצריכים עזרה, אם יש להם כסף?",options:["מכספם של ההורים","מקופת הקהילה","מכספו של הבן","מכספי מעשר בלבד"],answer:0,category:"halacha",difficulty:3,tags:["כיבוד הורים"],note:"הבן טורח בגופו, אבל אינו חייב להוציא מכספו אם יש להם."},
  {id:"halacha-0209",q:"מה עדיף לכתחילה לגבי הורים זקנים שצריכים טיפול?",options:["להשאיר אותם לבד","לשלוח לבית אבות","לשכור להם דירה רחוקה","להכניס אותם לבית הבן ולטפל בהם"],answer:3,category:"halacha",difficulty:2,tags:["כיבוד הורים"],note:"לכתחילה לא שולחים למושב זקנים."},
  {id:"halacha-0210",q:"אבא שלי אמר לי לא להחזיר אבידה שמצאתי. מה עושים?",options:["נותנים לצדקה","מחזירים בכל זאת","שומעים לאבא","שואלים את אמא"],answer:1,category:"halacha",difficulty:1,tags:["כיבוד הורים","השבת אבידה"],note:"גם האב וגם הבן חייבים במצוות הבורא."},
  {id:"halacha-0211",q:"לפי מנהג הספרדים, על שם מי קוראים לבן הראשון?",options:["על שם הרב","על שם סבא רבא","על שם אבי האם","על שם אבי הבעל"],answer:3,category:"halacha",difficulty:1,tags:["כיבוד הורים","מנהגים"],note:"ספרדים קוראים על שם ההורים גם בחייהם; הבן השני – על שם אבי האם."},
  {id:"halacha-0212",q:"לפי המנהג, את מי מכבדים בסנדקאות בבן הראשון?",options:["את אבי הבעל","את אבי האשה","את רב הקהילה","את האח הגדול"],answer:0,category:"halacha",difficulty:1,tags:["ברית מילה","מנהגים"],note:"בבן השני – את אבי האשה."},
  {id:"halacha-0213",q:"מה אומרים בשנה הראשונה לפטירת האב, כשמצטטים דבר הלכה בשמו?",options:["זכרונו לברכה בלבד","הריני כפרת משכבו","עליו השלום","נשמתו עדן"],answer:1,category:"halacha",difficulty:2,tags:["כיבוד הורים","אבלות"],note:"כך נוהגים בתוך שנים עשר חודש."},
  {id:"halacha-0214",q:"מותר לבן להתפלל עמידה ממש לצד אביו?",options:["רק בשבת","כן, אין בעיה","לא, בתוך ארבע אמות אין לעמוד לצדו","רק בבית הכנסת"],answer:2,category:"halacha",difficulty:3,tags:["כיבוד הורים","תפילה"],note:"יש לחשוש לזה גם בתפילה בציבור."},
  {id:"halacha-0215",q:"נסעתי רחוק וההורים דואגים. להתקשר ולהודיע שהגעתי – מצווה?",options:["רק בחו\"ל","לא, זו רשות","כן, מצוות כיבוד הורים","רק אם ביקשו"],answer:2,category:"halacha",difficulty:1,tags:["כיבוד הורים"],note:"מסירים דאגה מלבם."},
  {id:"halacha-0216",q:"לפי הדין, חובה לבקר את ההורים כל שבת וחג?",options:["רק אם הם גרים קרוב","כן, חובה גמורה","רק בחגים","אין חובה, אך ישתדל אם הם שמחים בזה"],answer:3,category:"halacha",difficulty:3,tags:["כיבוד הורים"],note:"ישתדל לעשות רצונם ככל שיוכל."},
  {id:"halacha-0217",q:"מותר לבן לומר לאביו \"אתה טועה\" בדיון?",options:["רק בפני אחרים","לא, אין סותרים את דברי ההורים","כן, בנימוס","כן, אם צודק"],answer:1,category:"halacha",difficulty:3,tags:["כיבוד הורים","מורא"],note:"אבל להשיב לחולקים על אביו – מותר, כי זה כבודו."},
  {id:"halacha-0218",q:"מי שיכול לפרנס את הוריו מכספו – מותר לו לעשות זאת מכספי צדקה?",options:["רק אם הם לא יודעים","כן, מכל המעשר","לא, יש בזה ביזיון להם","כן, ממחצית המעשר"],answer:2,category:"halacha",difficulty:3,tags:["כיבוד הורים","צדקה"],note:"מי שאינו יכול – רשאי לפרנסם מהצדקה."},
  {id:"halacha-0219",q:"מתארח אצל ההורים כשהם לא בבית. מותר לישון במיטה שלהם?",options:["כן","לא","רק ביום","רק אם היא מסודרת"],answer:1,category:"halacha",difficulty:1,tags:["כיבוד הורים"],note:"אין לישון על מיטת אביו או אמו."},
  {id:"halacha-0220",q:"אבא טס בבוקר. מותר ללוות אותו לשדה התעופה לפני שחרית?",options:["לא, קודם מתפללים","רק אם יש מניין בשדה","כן, וקורא קריאת שמע קודם","רק אם הוא מבקש"],answer:2,category:"halacha",difficulty:3,tags:["כיבוד הורים"],note:"ונפרדים ב\"נסיעה טובה\" ולא ב\"שלום\"."},
  {id:"halacha-0221",q:"מצוות כיבוד אב ואם כוללת מעשה, דיבור ו...",options:["צום","ממון","שירה","מחשבה"],answer:3,category:"halacha",difficulty:1,tags:["כיבוד הורים"],note:"במעשה, בדיבור ובמחשבה."},
  {id:"halacha-0222",q:"איך מכבדים הורים אחרי פטירתם?",options:["רק בבניית מצבה גדולה","בקדיש, בלימוד ובהדלקת נר ביום הפטירה","אין חובה לכבדם","רק בביקור בקבר"],answer:1,category:"halacha",difficulty:2,tags:["כיבוד הורים","אבלות"],note:"עיקר הכבוד לעשות להם נחת רוח."},
  {id:"halacha-0223",q:"באיזה זמן ביום עדיף לערוך ברית מילה?",options:["בצהריים","אחר הצהריים","בבוקר","בערב"],answer:2,category:"halacha",difficulty:1,tags:["ברית מילה"],note:"זריזים מקדימים למצוות."},
  {id:"halacha-0224",q:"מתי אבי הבן מברך \"שהחיינו\" בברית?",options:["בסעודה","בקידוש של שבת","מיד אחרי המילה","לפני הברית"],answer:2,category:"halacha",difficulty:2,tags:["ברית מילה"],note:"ומברכים על כל בן, לא רק על הבכור."},
  {id:"halacha-0225",q:"למה לא מזמינים במפורש לסעודת ברית?",options:["כי אסור לאכול בה בשר","כי זה ביום חול","כי זו סעודה קטנה","כי מי שהוזמן ולא בא \"כמנודה לשמים\""],answer:3,category:"halacha",difficulty:2,tags:["ברית מילה"],note:"מודיעים על המועד בלבד."},
  {id:"halacha-0226",q:"מותר לאכול בשר בסעודת ברית מילה בתשעת הימים?",options:["רק עוף","לא","רק אבי הבן","כן"],answer:3,category:"halacha",difficulty:1,tags:["ברית מילה","בין המצרים"],note:"כל הקרואים לסעודה רשאים לאכול בשר."},
  {id:"halacha-0227",q:"אחרי כמה ימים מהלידה עורכים פדיון הבן?",options:["8","13","30","40"],answer:2,category:"halacha",difficulty:2,tags:["פדיון הבן"],note:"פודים מיד אחרי שעברו שלושים יום."},
  {id:"halacha-0228",q:"יום השלושים ואחד ללידת הבכור חל בשבת. מתי פודים?",options:["בשבת עצמה","ביום ראשון","ביום שישי","בעוד שבוע"],answer:1,category:"halacha",difficulty:3,tags:["פדיון הבן","שבת"],note:"אין פודים בשבת."},
  {id:"halacha-0229",q:"בכור שנולד בניתוח קיסרי – צריך פדיון?",options:["רק בלי ברכה","רק אם הוא בכור לאביו","לא","כן"],answer:2,category:"halacha",difficulty:1,tags:["פדיון הבן"],note:"קדושת בכור היא רק ב\"פטר רחם\"."},
  {id:"halacha-0230",q:"כמה גרם כסף טהור נותנים לכהן בפדיון הבן, לפי מנהג ירושלים?",options:["30","50","93","120"],answer:2,category:"halacha",difficulty:3,tags:["פדיון הבן"],note:"שלושים ואחד דרהם, כתשעים ושלושה גרם; מעיקר הדין די בכתשעים."},
  {id:"halacha-0231",q:"על מי חלה חובת פדיון הבן?",options:["על האם","על האב","על הסבא","על הכהן"],answer:1,category:"halacha",difficulty:1,tags:["פדיון הבן"],note:"אם האם פדתה – הבן אינו פדוי."},
  {id:"halacha-0232",q:"מה ההלכה לגבי חתונה בחודש אלול?",options:["אסור","מותר, אין בזה חשש","רק עד ראש חודש אלול","רק אחרי ראש השנה"],answer:1,category:"halacha",difficulty:1,tags:["נישואין"],note:"מותר גם בעשרת ימי תשובה."},
  {id:"halacha-0233",q:"מותר לעשות חתונה בחול המועד?",options:["לא, אבל מותר לעשות וורט","רק בסוכות","כן","רק בפסח"],answer:0,category:"halacha",difficulty:1,tags:["נישואין","מועדים"],note:"בחול המועד אין נושאים נשים, אבל שידוכין מותרים."},
  {id:"halacha-0234",q:"למנהג הספרדים, עד מתי נוהגים להתחתן בקיץ לפני תשעה באב?",options:["עד י\"ז בתמוז","עד ליל ראש חודש אב","עד ערב תשעה באב","עד ראש חודש תמוז"],answer:1,category:"halacha",difficulty:3,tags:["נישואין","בין המצרים"],note:"למנהג הספרדים מותר בתמוז עד ר\"ח אב."},
  {id:"halacha-0235",q:"לפי מנהג הספרדים, חתן מתענה ביום חתונתו?",options:["לא","רק אם החתונה ביום חמישי","כן, עד החופה","רק בבוקר"],answer:0,category:"halacha",difficulty:1,tags:["נישואין","מנהגים"],note:"ראוי שיעסוק בתורה ובתענית דיבור."},
  {id:"halacha-0236",q:"מתי ראוי לצעוק \"מזל טוב\" בחופה?",options:["בסיום מעמד החופה","לפני הקידושין","בזמן הכתובה","מיד בשבירת הכוס"],answer:0,category:"halacha",difficulty:1,tags:["נישואין"],note:"שבירת הכוס היא זכר לחורבן."},
  {id:"halacha-0237",q:"איך מקיימים מצוות שמחת חתן וכלה?",options:["בשבחים או בריקוד לפניהם","רק במתנה","רק בנוכחות בחופה","רק בברכה בכתב"],answer:0,category:"halacha",difficulty:1,tags:["נישואין"],note:"די באחד מהם."},
  {id:"halacha-0238",q:"כמה \"פנים חדשות\" צריך לפחות כדי לברך שבע ברכות בסעודה?",options:["1","2","3","10"],answer:1,category:"halacha",difficulty:3,tags:["נישואין"],note:"המנהג בארץ – לפחות שניים שהם פנים חדשות."},
  {id:"halacha-0239",q:"לכמה ימים נוהגים חתן וכלה בשמחת \"שבע ברכות\"?",options:["3","7","8","30"],answer:1,category:"halacha",difficulty:1,tags:["נישואין"],note:"חכמים תיקנו שבעת ימי משתה."},
  {id:"halacha-0240",q:"יודעים על מחלה רצינית של אחד הצדדים בשידוך. מה הדין?",options:["אסור לספר, זה לשון הרע","צריך לחכות לאחר החתונה","רק אם שואלים","חובה להודיע למשפחות"],answer:3,category:"halacha",difficulty:2,tags:["נישואין","לשון הרע"],note:"בפרט במחלה שיש בה סכנה."},
  {id:"halacha-0241",q:"כמה גברים צריך כדי לומר קדיש?",options:["3","7","10","12"],answer:2,category:"halacha",difficulty:1,tags:["קדיש","אבלות"],note:"אומרים קדיש רק במניין."},
  {id:"halacha-0242",q:"על כמה קרובים יושבים שבעה?",options:["3","5","7","10"],answer:2,category:"halacha",difficulty:1,tags:["אבלות"],note:"אב, אם, אח, אחות, בן, בת ובן/בת זוג."},
  {id:"halacha-0243",q:"מה מברכים בשעת הקריעה על קרוב שנפטר?",options:["הטוב והמטיב","ברוך שם כבוד מלכותו","דיין האמת","שהחיינו"],answer:2,category:"halacha",difficulty:1,tags:["אבלות"],note:"מברכים \"ברוך... דיין האמת\"."},
  {id:"halacha-0244",q:"איך קוראים לקרוב שנפטר לו מת ועדיין לא נקבר?",options:["שומר","אונן","אבל","מתאבל"],answer:1,category:"halacha",difficulty:1,tags:["אבלות"],note:"האונן פטור מכל המצוות."},
  {id:"halacha-0245",q:"אונן (לפני הקבורה) רוצה לאכול לחם. האם הוא מברך?",options:["כן, כרגיל","לא, אינו מברך לפני ולא אחרי","מברך רק ברכת המזון","מברך בלחש"],answer:1,category:"halacha",difficulty:2,tags:["אבלות","ברכות"],note:"רשאי לאכול ולשתות אך אינו מברך."},
  {id:"halacha-0246",q:"מתי מתחילה השבעה?",options:["מרגע הפטירה","מסתימת הגולל בקבר","מצאת הכוכבים שאחרי הקבורה","למחרת הקבורה"],answer:1,category:"halacha",difficulty:2,tags:["אבלות"],note:"היום הנחת הלבנים בקבר נחשבת סתימת הגולל."},
  {id:"halacha-0247",q:"לפי המנהג היום, יושבים שבעה על חמי וחמותי?",options:["לא","רק שלושה ימים","רק הבעל","כן"],answer:0,category:"halacha",difficulty:1,tags:["אבלות"],note:"הכל נהגו למחול, ואין להחמיר."},
  {id:"halacha-0248",q:"איזה מהבאים מותר לאבל בתוך השבעה?",options:["לנעול נעלי בד","ללמוד גמרא","לכבס בגדים","לעבוד במשרד"],answer:0,category:"halacha",difficulty:1,tags:["אבלות"],note:"נעלי עור אסורות, נעלי בד וגומי מותרות."},
  {id:"halacha-0249",q:"מותר לאבל לרחוץ את פניו בשבעה?",options:["כן, במים קרים","רק בשבת","לא, כלל לא","כן, במים חמים"],answer:0,category:"halacha",difficulty:1,tags:["אבלות"],note:"פנים, ידיים ורגליים בצונן – מותר."},
  {id:"halacha-0250",q:"איזה לימוד מותר לאבל בשבעה?",options:["תהילים בציבור","פרק \"אלו מגלחים\" ודיני אבלות","פרשת השבוע","גמרא בעיון"],answer:1,category:"halacha",difficulty:3,tags:["אבלות"],note:"\"פקודי ה' ישרים משמחי לב\", לכן לומד רק דברים המותרים לו."},
  {id:"halacha-0251",q:"מי פותח בדיבור בניחום אבלים?",options:["הרב","המנחם הראשון","האבל","המבוגר שבמנחמים"],answer:2,category:"halacha",difficulty:1,tags:["אבלות","ניחום אבלים"],note:"המנחמים אינם רשאים לפתוח עד שהאבל מתחיל."},
  {id:"halacha-0252",q:"מה נוהגים לומר לאבלים כשיוצאים מניחום?",options:["חזק וברוך","תנוחמו מן השמים","מזל טוב","בשורות טובות"],answer:1,category:"halacha",difficulty:1,tags:["אבלות","ניחום אבלים"],note:"ויש מוסיפים \"ולא תוסיפו לדאבה עוד\"."},
  {id:"halacha-0253",q:"למה מכסים מראות בבית האבל?",options:["כדי לחסוך בחשמל","זו חובה מן התורה","כדי שלא יראו את האבלים","זה מנהג, בעיקר כשמתפללים בבית"],answer:3,category:"halacha",difficulty:2,tags:["אבלות","מנהגים"],note:"אם אין מתפללים בבית האבל אין צורך לכסות."},
  {id:"halacha-0254",q:"אבל בשבת שבתוך השבעה – איך נוהג?",options:["אבלות רק בדברים שבצנעה","מתחיל את השבעה מחדש","כרגיל בשבעה","השבת מפסיקה את השבעה"],answer:0,category:"halacha",difficulty:2,tags:["אבלות","שבת"],note:"השבת נמנית במניין השבעה."},
  {id:"halacha-0255",q:"מתי קמים מהשבעה ביום השביעי?",options:["אחרי שחרית ואחרי הזריחה","בחצות היום","בבוקר היום השמיני","בצאת הכוכבים"],answer:0,category:"halacha",difficulty:2,tags:["אבלות"],note:"מקצת היום ככולו."},
  {id:"halacha-0256",q:"כמה זמן אסור לאבל להסתפר ולהתגלח?",options:["30 יום","12 חודש","3 ימים","7 ימים"],answer:0,category:"halacha",difficulty:1,tags:["אבלות"],note:"שלושים יום, בשער הראש, הזקן ובכל שער."},
  {id:"halacha-0257",q:"כמה זמן אבל על אב או אם נמנע מלשמוע מוזיקה?",options:["30 יום","12 חודש","7 ימים","3 חודשים"],answer:1,category:"halacha",difficulty:2,tags:["אבלות"],note:"על שאר קרובים – שלושים יום."},
  {id:"halacha-0258",q:"כמה זמן אומרים קדיש על אב או אם?",options:["שנים עשר חודש, עם הפסקה קצרה","30 יום","7 ימים","שלוש שנים"],answer:0,category:"halacha",difficulty:2,tags:["קדיש","אבלות"],note:"מפסיקים כשבוע בתחילת החודש ה־12 וחוזרים עד יום השנה."},
  {id:"halacha-0259",q:"יום השנה (יארצייט) נקבע לפי איזה יום?",options:["יום הקמת המצבה","יום הפטירה","יום הקבורה","יום סיום השבעה"],answer:1,category:"halacha",difficulty:1,tags:["אבלות"],note:"גם בשנה הראשונה הולכים אחר יום הפטירה."},
  {id:"halacha-0260",q:"מה מרבים לעשות ביום השנה של ההורים?",options:["נסיעה לחו\"ל","סעודה גדולה בלי תורה","לימוד תורה וצדקה","צום שלושה ימים"],answer:2,category:"halacha",difficulty:1,tags:["אבלות"],note:"ביום ובלילה שלפניו."},
  {id:"halacha-0261",q:"מה קורה לשבעה כשחג מתחיל באמצעה?",options:["השבעה מתחילה מחדש אחרי החג","החג נדחה","החג מפסיק את השבעה","השבעה נמשכת בחג"],answer:2,category:"halacha",difficulty:2,tags:["אבלות","מועדים"],note:"מפני מצוות שמחת החג."},
  {id:"halacha-0262",q:"לפי ילקוט יוסף, מה המנהג הנכון לגבי זמן הקמת המצבה?",options:["כבר ביום השביעי","אחרי שלוש שנים","רק בסוף השנה","רק בשלושים"],answer:0,category:"halacha",difficulty:3,tags:["אבלות"],note:"שלא לאחר את המצבה אחרי היום השביעי."},
  {id:"halacha-0263",q:"לוויה עוברת לידי. מה הדין?",options:["אין חובה","רק קרובי משפחה","רק אם מכירים","יש מצווה ללוות את המת"],answer:3,category:"halacha",difficulty:1,tags:["אבלות","חסד"],note:"הרואה מת ואינו מלווהו עובר על \"לועג לרש\"."},
  {id:"halacha-0264",q:"נשים קורעות קריעה על קרוב שנפטר?",options:["רק בשבעה","לא","כן, כמו הגברים","רק על הורים"],answer:2,category:"halacha",difficulty:1,tags:["אבלות","נשים"],note:"וסוגרות את הקרע בסיכה לצניעות."},
  {id:"halacha-0265",q:"לפי המנהג, מה מדליקים בבית הנפטר כל השבעה?",options:["מנורת חנוכה","נר הבדלה","נר שמן","נר שבת בלבד"],answer:2,category:"halacha",difficulty:2,tags:["אבלות","מנהגים"],note:"\"נר ה' נשמת אדם\"."},
  {id:"halacha-0266",q:"יוצאים ידי מצוות ביקור חולים בשיחת טלפון?",options:["כן, לגמרי","לא בשלמות; עיקרה ביקור בגוף","רק בשבת","רק אם החולה מבקש"],answer:1,category:"halacha",difficulty:1,tags:["ביקור חולים","חסד"],note:"אם אפשר – הולכים בעצמם."},
  {id:"halacha-0267",q:"מה אומרים לחולה כשמבקרים אותו בשבת?",options:["שבת שלום ומבורך","חזק ואמץ","שבת היא מלזעוק ורפואה קרובה לבוא","רפואה שלמה בלבד"],answer:2,category:"halacha",difficulty:2,tags:["ביקור חולים","שבת"],note:"נוסח מיוחד לשבת."},
  {id:"halacha-0268",q:"למה משנים או מוסיפים שם לחולה קשה?",options:["כדי לכבד את הסבא","זה מנהג חדש","כדי שהרופאים לא יזהו אותו","זה אחד הדברים שקורעים גזר דין"],answer:3,category:"halacha",difficulty:2,tags:["ביקור חולים","מנהגים"],note:"שינוי השם הוא מהדברים הקורעים את גזר הדין."},
  {id:"halacha-0269",q:"כמה זמן צריך להישאר אצל חולה?",options:["בדיוק שעה","לפחות שלוש שעות","עשר דקות בלבד","אין שיעור, אך לא להכביד עליו"],answer:3,category:"halacha",difficulty:1,tags:["ביקור חולים"],note:"כל המרבה משובח, ובלבד שלא יכביד."},
  {id:"halacha-0270",q:"לכתחילה, מתי אין לקרוא תהילים לרפואת חולה?",options:["בלילה לפני חצות","בראש חודש","בבוקר","בשבת אחר הצהריים"],answer:0,category:"halacha",difficulty:3,tags:["ביקור חולים","תהילים"],note:"בזמן הזה לומדים במקום זה פתח אליהו, משניות או תנ\"ך עם רש\"י."},
  {id:"halacha-0271",q:"איך ראוי לבקש רחמים על חולה?",options:["לומר \"שיהיה בריא\" ותו לא","בלשון בקשה, \"יהי רצון...\"","בשתיקה בלבד","רק בכתב"],answer:1,category:"halacha",difficulty:1,tags:["ביקור חולים"],note:"עיקר הביקור לצורכי החולה ולעודד את רוחו."},
  {id:"halacha-0272",q:"עני מבקש צדקה. איך ראוי לתת?",options:["רק סכום גדול","בסבר פנים יפות, אפילו סכום קטן","רק דרך העמותה","עדיף לא לתת כלום"],answer:1,category:"halacha",difficulty:1,tags:["צדקה","חסד"],note:"הנותן בפנים זועפות מפסיד את זכותו."},
  {id:"halacha-0273",q:"לפי הנפסק, מעשר כספים מהמשכורת – חובה גמורה?",options:["אסור לתת יותר ממעשר","רק לבעלי עסקים","אין חובה גמורה, אך רבים נוהגים","חובה מן התורה"],answer:2,category:"halacha",difficulty:2,tags:["צדקה","מעשר"],note:"טוב להתנות מראש שיוכל לעשות במעות המעשר כל מצווה."},
  {id:"halacha-0274",q:"מאיזה גיל אפשר לנכות ממעשר כספים את הוצאות פרנסת הילדים?",options:["מגיל אפס","מעל גיל שש","מעל גיל שמונה עשרה","מעל גיל שלוש עשרה"],answer:1,category:"halacha",difficulty:3,tags:["צדקה","מעשר"],note:"גם כשהם סמוכים על שולחנו."},
  {id:"halacha-0275",q:"למי קודם לתת צדקה, כשהצורך שווה?",options:["למי שמודה הכי הרבה","לקרוב משפחה","לאדם זר מרוחק","למי שמבקש בקול רם"],answer:1,category:"halacha",difficulty:1,tags:["צדקה"],note:"\"קרוב קרוב קודם\", ומעדיפים בן תורה."},
  {id:"halacha-0276",q:"מותר לשלם שכר לימוד תורה של הילד מכספי המעשר?",options:["כן","לא","רק בחצי","רק לבנות"],answer:0,category:"halacha",difficulty:1,tags:["צדקה","מעשר"],note:"מותר לתת למלמד או לישיבה שבה לומד בנו."},
  {id:"halacha-0277",q:"מותר לתת צדקה בלילה?",options:["רק לפני חצות","לא, רק ביום","רק בשבת","כן, מעיקר הדין"],answer:3,category:"halacha",difficulty:1,tags:["צדקה"],note:"יש שכתבו על פי האר\"י שלא לתת, אך מעיקר הדין אין להקפיד."},
  {id:"halacha-0278",q:"נשים חייבות במצוות צדקה?",options:["רק מכספן הפרטי בחגים","לא","רק נשואות","כן"],answer:3,category:"halacha",difficulty:1,tags:["צדקה","נשים"],note:"הנשים חייבות במצוות צדקה."},
  {id:"halacha-0279",q:"מותר להעלות מחיר במכירת עליות רק כדי שאחר יוסיף ויתן יותר?",options:["כן, זה לטובת בית הכנסת","רק בשמחת תורה","רק אם הגבאי מבקש","לא"],answer:3,category:"halacha",difficulty:1,tags:["צדקה","בית הכנסת"],note:"זה כמי שפוסק צדקה ברבים ואינו נותן."},
  {id:"halacha-0280",q:"מה עושים בכסף מקופת צדקה ישנה של מוסד שנסגר ואין לו כתובת?",options:["נותנים לכל מי שרוצה","לוקחים לעצמנו","זורקים","נשאלים לחכם ונותנים למוסד דומה"],answer:3,category:"halacha",difficulty:2,tags:["צדקה","נדרים"],note:"מעבירים למוסדות שמטרתם דומה."},
  {id:"halacha-0281",q:"עד כמה מותר לסטות ממחיר השוק בלי שזו \"אונאה\" שמחייבת החזר?",options:["עד שליש","פחות משישית","אסור לסטות כלל","עד חצי"],answer:1,category:"halacha",difficulty:3,tags:["ממון","אונאה"],note:"משישית – מחזירים הפרש; יותר משישית – העסקה בטלה."},
  {id:"halacha-0282",q:"עסקה נעשתה ביותר משישית ממחיר השוק. מה הדין?",options:["העסקה קיימת לגמרי","המוכר משלם קנס","העסקה בטלה","מחזירים את ההפרש"],answer:2,category:"halacha",difficulty:3,tags:["ממון","אונאה"],note:"ביותר משישית – ביטול מקח."},
  {id:"halacha-0283",q:"על איזה סוג נכס אין דין אונאה?",options:["רכב","קרקע","ביגוד","מזון"],answer:1,category:"halacha",difficulty:3,tags:["ממון","אונאה"],note:"בקרקעות אין אונאה."},
  {id:"halacha-0284",q:"שילמתי מקדמה והמוכר רוצה לחזור בו. מה הדין?",options:["מותר לחזור בלי בעיה","רק הקונה רשאי לחזור","מי שחוזר מקבל את קללת \"מי שפרע\"","המוכר חייב לשלם כפול"],answer:2,category:"halacha",difficulty:2,tags:["ממון","מקח וממכר"],note:"אחרי שנתן כסף – החוזר \"לא עשה מעשה ישראל\"."},
  {id:"halacha-0285",q:"מותר לטעום דוגמיות בשוק כשאין שום כוונה לקנות?",options:["רק מוצר אחד","רק בשבת","כן, זה מקובל","לא, זו גניבת דעת"],answer:3,category:"halacha",difficulty:1,tags:["ממון","גניבת דעת"],note:"מי שבאמת מתכוון לקנות – רשאי לטעום."},
  {id:"halacha-0286",q:"מציעים לי בזול מוצר שכנראה גנוב. מותר לקנות?",options:["לא, זה מחזק ידי עוברי עבירה","רק לצורך מתנה","כן, אם המחיר טוב","כן, אם לא שואלים"],answer:0,category:"halacha",difficulty:1,tags:["ממון","גזל"],note:"הקונה גורם לגנב להמשיך לגנוב."},
  {id:"halacha-0287",q:"לפי מרן השולחן ערוך, מה דינו של ספרדי בקניית כרטיס לוטו?",options:["מותר לכתחילה","מותר רק בפורים","מותר אם תורם את הזכייה","אסור, משום אסמכתא"],answer:3,category:"halacha",difficulty:3,tags:["ממון","הגרלות"],note:"הגרלה על חפץ מסוים, שמי שעולה בגורל זוכה בו – מותרת."},
  {id:"halacha-0288",q:"מה זו \"ריבית דברים\"?",options:["להזכיר ללווה את החוב","לבקש הלוואה בדיבור בלבד","לחלוק כבוד למלווה רק בגלל ההלוואה","לדבר על ריבית בבנק"],answer:2,category:"halacha",difficulty:3,tags:["ממון","ריבית"],note:"למשל להתחיל להקדים לו שלום בגלל ההלוואה."},
  {id:"halacha-0289",q:"מי שהלווה לי כסף רוצה לשכור ממני דירה. מה מותר?",options:["להשכיר במחיר הרגיל שפורסם לכולם","לתת לו הנחה קטנה","לתת לו חודש חינם","לוותר על הפיקדון"],answer:0,category:"halacha",difficulty:3,tags:["ממון","ריבית"],note:"הנחה בגלל ההלוואה – חשש ריבית."},
  {id:"halacha-0290",q:"מצאתי שטרות מפוזרים ברחוב בלי סימן. מה הדין?",options:["חובה להכריז","חובה למסור לבית הכנסת","מותר לקחת, הבעלים התייאשו","אסור לגעת"],answer:2,category:"halacha",difficulty:1,tags:["השבת אבידה"],note:"אבל מטבעות מסודרות – חייב להכריז."},
  {id:"halacha-0291",q:"ראיתי תיק מונח על ספסל, כאילו מישהו הניח אותו. מה עושים?",options:["לא נוגעים בו","לוקחים כדי להחזיר","לוקחים ותולים מודעה","לוקחים לעצמי"],answer:0,category:"halacha",difficulty:2,tags:["השבת אבידה"],note:"אולי הבעלים הניחו אותו שם ויחזרו."},
  {id:"halacha-0292",q:"דיברתי לשון הרע על מישהו שלא יודע על כך. איך מבקשים סליחה?",options:["באופן כללי, בלי לספר מה נאמר","שולחים מכתב לכל השכנים","מספרים לו כל מה שאמרתי","לא מבקשים כלל"],answer:0,category:"halacha",difficulty:2,tags:["לשון הרע","תשובה"],note:"הסיפור עלול להגדיל את צערו."},
  {id:"halacha-0293",q:"העלבתי מישהו רק במילים. צריך לבקש ממנו סליחה?",options:["כן, אונאת דברים חמורה מאוד","לא, רק על נזק בממון","רק אם הוא דרש","רק לפני יום כיפור"],answer:0,category:"halacha",difficulty:1,tags:["אונאת דברים","תשובה"],note:"אונאת דברים חמורה מאונאת ממון."},
  {id:"halacha-0294",q:"מותר להשאיר כסף על השולחן כדי לבדוק אם העובדת תיקח?",options:["לא, זה \"לפני עיוור לא תתן מכשול\"","רק סכום קטן","רק פעם אחת","כן, זה מותר"],answer:0,category:"halacha",difficulty:2,tags:["לפני עיוור","מידות"],note:"יש מקלים, אך הדעה העיקרית אוסרת."},
  {id:"halacha-0295",q:"מותר לנגב ידיים במגבת של חבר בלי רשותו?",options:["רק אחרי נטילה","לא","רק אם היא רטובה","כן"],answer:1,category:"halacha",difficulty:1,tags:["גזל","מידות"],note:"אסור להשתמש בחפץ של חבר בלי רשותו."},
  {id:"halacha-0296",q:"מותר להעתיק לגמרי אלבום מוזיקה שכתוב עליו \"כל הזכויות שמורות\"?",options:["לא","כן, אם הוא ישן","רק בחו\"ל","כן, לשימוש אישי"],answer:0,category:"halacha",difficulty:1,tags:["ממון","זכויות יוצרים"],note:"אבל מותר להקליט שירים מהרדיו או דברי תורה."},
  {id:"halacha-0297",q:"שתי מכוניות נתקעו מול זו בכביש צר. מה ההנחיה?",options:["המבוגר עובר","לנהוג לפי החוק, ולוותר זה לזה","הגדול תמיד עובר","מי שהגיע ראשון עובר"],answer:1,category:"halacha",difficulty:1,tags:["נהיגה","מידות"],note:"אם אין כלל בחוק – נותנים לאוטובוס הציבורי לעבור."},
  {id:"halacha-0298",q:"מה עיקר מצוות לימוד תורה?",options:["הקשבה לשיעור ברדיו","נשיאת ספר","לימוד מתוך הבנת העניין","קריאת פסוקים בלבד"],answer:2,category:"halacha",difficulty:1,tags:["לימוד תורה"],note:"לא די בקריאה, ואפילו לא בהבנת פירוש המילים."},
  {id:"halacha-0299",q:"מי שאינו יכול ללמוד הרבה – מה ראוי שיעשה?",options:["לתמוך בעין יפה במוסדות תורה","לקנות ספרים ולא לפתוח","אין לו מה לעשות","לצום פעם בשבוע"],answer:0,category:"halacha",difficulty:2,tags:["לימוד תורה","צדקה"],note:"כך יש לו חלק בתורה."},
  {id:"halacha-0300",q:"נשים פטורות ממצוות תלמוד תורה, אבל מה עליהן ללמוד?",options:["שום דבר","רק תהילים","רק פרשת השבוע","את הדינים השייכים להן"],answer:3,category:"halacha",difficulty:2,tags:["לימוד תורה","נשים"],note:"כמו הלכות שבת, ברכות, כשרות ובשר וחלב."},
  {id:"halacha-0301",q:"אני באמצע לימוד, והגיע זמן קריאת שמע. מה קודם?",options:["תלוי מה מעניין יותר","לסיים את הפרק","הלימוד","קריאת שמע"],answer:3,category:"halacha",difficulty:1,tags:["לימוד תורה","מצוות"],note:"מצווה שאי אפשר שתיעשה על ידי אחרים קודמת לתלמוד תורה."},
  {id:"halacha-0302",q:"לפי הנפסק, מותר לקנות בחו\"ל שוקולד בלי הכשר?",options:["לא, בגלל חשש תערובת איסור","כן, שוקולד תמיד כשר","רק שוקולד מריר","רק אם קנוי בדיוטי פרי"],answer:0,category:"halacha",difficulty:1,tags:["כשרות","חו\"ל"],note:"ממתקים עם הכשר רבנות אמינה – אפשר."},
  {id:"halacha-0303",q:"בטיסה של חברה זרה – באיזו כוס עדיף לשתות קפה?",options:["בכוס מתכת","אין הבדל","בכוס הפורצלן של החברה","בכוס זכוכית"],answer:3,category:"halacha",difficulty:3,tags:["כשרות","נסיעות"],note:"יש לחשוש שבכוסות השתמשו בחלב של גויים; בשעת הדחק – פורצלן."},
  {id:"halacha-0304",q:"מותר להניח אוכל במזוודה בבטן המטוס כשנוסעים ישנים מעליו?",options:["רק אוכל סגור בשני כלים","רק בטיסות קצרות","כן, מותר לכתחילה","לא, זה מסוכן רוחנית"],answer:2,category:"halacha",difficulty:1,tags:["נסיעות"],note:"אין חשש בהנחת מאכלים במטען."},
  {id:"halacha-0305",q:"לפי הנפסק, מותר לספרדי לשבת עם חברים לקפה בבית קפה של גויים בחו\"ל?",options:["מותר לגמרי","אין לשתות שם, משום קירוב דעת","רק קפה שחור","רק בשעות הבוקר"],answer:1,category:"halacha",difficulty:3,tags:["כשרות","חו\"ל"],note:"אך המתארח בבית גוי שמכבדו בקפה – רשאי."},
  {id:"halacha-0306",q:"אני אורח, והמארח מגיש לי מאכל כשר לגמרי. מה הנימוס ההלכתי?",options:["לבקש מאכל אחר","לאכול רק חצי","לסרב פעמיים","לשמוע לבעל הבית"],answer:3,category:"halacha",difficulty:2,tags:["דרך ארץ","אירוח"],note:"הנכנס לבית חבירו יעשה כל מה שאומר בעל הבית."},
];
